import React from "react";
import { AbsoluteFill, Sequence, useCurrentFrame, useVideoConfig, interpolate, spring, Easing, random } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { startFrame: number; endFrame?: number; word?: string; text?: string; index?: number; wordIndex?: number };
type ShotProps = { wordCues?: WordCue[] };
type View = { z: number; cx: number; cy: number };

const C = {
  ivory: "#F3F1E9",
  white: "#FFFFFF",
  graphite: "#172833",
  gray: "#9AA8AD",
  teal: "#167D8D",
  coral: "#EE735E",
};
const UI = "'Inter', 'Arial', sans-serif";
const MONO = "'IBM Plex Mono', 'Courier New', monospace";
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const ease = Easing.bezier(0.4, 0, 0.2, 1);
const smooth = (f: number, a: number, b: number) => interpolate(f, [a, b], [0, 1], { ...clamp, easing: ease });
const mix = (a: number, b: number, t: number) => a + (b - a) * t;
const mixView = (a: View, b: View, t: number): View => ({ z: mix(a.z, b.z, t), cx: mix(a.cx, b.cx, t), cy: mix(a.cy, b.cy, t) });

// All five panels use the same geometry, rows, weight, and registration pattern.
const peers = [
  { x: 480, y: 240 },
  { x: 950, y: 240 },
  { x: 715, y: 580 },
  { x: 245, y: 580 },
  { x: 1185, y: 580 },
];
const PW = 310;
const PH = 254;
const TW = 252;
const TH = 58;
const ROW_Y = [72, 133, 194];
const TARGET = { x: peers[2].x + 29, y: peers[2].y + ROW_Y[0] };
const BOX = { x: 570, y: 300, w: 460, h: 370 };
const EDGES: [number, number][] = [[0, 1], [0, 3], [0, 2], [1, 2], [1, 4], [3, 2], [2, 4], [3, 4]];

const RegistrationCorners = () => (
  <>
    {[
      { left: 6, top: 6, borderLeft: `2px solid ${C.teal}`, borderTop: `2px solid ${C.teal}` },
      { right: 6, top: 6, borderRight: `2px solid ${C.teal}`, borderTop: `2px solid ${C.teal}` },
      { left: 6, bottom: 6, borderLeft: `2px solid ${C.teal}`, borderBottom: `2px solid ${C.teal}` },
      { right: 6, bottom: 6, borderRight: `2px solid ${C.teal}`, borderBottom: `2px solid ${C.teal}` },
    ].map((style, i) => <div key={i} style={{ position: "absolute", width: 10, height: 10, ...style }} />)}
  </>
);

const RecordFace: React.FC<{ active: number; ink?: number; ticket?: boolean }> = ({ active, ink = 1, ticket = false }) => (
  <div style={{ position: "relative", width: TW, height: TH, overflow: "hidden", borderRadius: 5, background: ticket ? C.white : "rgba(255,255,255,0.76)", border: `1px solid ${ticket ? "rgba(23,40,51,0.24)" : "rgba(23,40,51,0.09)"}`, boxSizing: "border-box" }}>
    <div style={{ position: "absolute", inset: 0, opacity: active, background: "rgba(22,125,141,0.095)", border: `1px solid rgba(22,125,141,0.42)`, borderRadius: 4 }} />
    <div style={{ position: "absolute", inset: 0, opacity: ink }}>
      <div style={{ position: "absolute", left: 23, top: 15, width: 21, height: 28, border: `1px solid ${C.gray}`, background: "rgba(154,168,173,0.12)" }} />
      <div style={{ position: "absolute", left: 59, top: 17, width: 132, height: 3, background: C.gray, opacity: 0.62 }} />
      <div style={{ position: "absolute", left: 59, top: 28, width: 85, height: 3, background: C.gray, opacity: 0.48 }} />
      <div style={{ position: "absolute", left: 59, top: 39, width: 110, height: 3, background: C.gray, opacity: 0.4 }} />
      {[0, 1, 2].map(i => <div key={i} style={{ position: "absolute", left: 206 + i * 6, top: 22, width: 2, height: [14, 20, 10][i], background: C.gray, opacity: 0.48 }} />)}
    </div>
    <div style={{ position: "absolute", inset: 0, opacity: active * ink }}>
      <RegistrationCorners />
      <div style={{ position: "absolute", left: 23, top: 15, width: 21, height: 28, border: `1px solid ${C.teal}`, background: "rgba(22,125,141,0.17)", boxSizing: "border-box" }} />
      <div style={{ position: "absolute", left: 29, top: 20, width: 9, height: 3, background: C.teal }} />
      <div style={{ position: "absolute", left: 29, top: 28, width: 9, height: 10, borderTop: `2px solid ${C.teal}`, borderBottom: `2px solid ${C.teal}`, boxSizing: "border-box" }} />
      <div style={{ position: "absolute", left: 59, top: 17, width: 132, height: 3, background: C.teal }} />
      <div style={{ position: "absolute", left: 59, top: 28, width: 85, height: 3, background: C.teal, opacity: 0.82 }} />
      <div style={{ position: "absolute", left: 59, top: 39, width: 110, height: 3, background: C.teal, opacity: 0.64 }} />
      {[0, 1, 2].map(i => <div key={i} style={{ position: "absolute", left: 206 + i * 6, top: 22, width: 2, height: [14, 20, 10][i], background: C.teal }} />)}
    </div>
  </div>
);

// Exactly eight simple SVG parts: body, lid, slot, two edges, inset, two base rules.
const BallotBox: React.FC<{ opening: number; opacity: number; arrival: number }> = ({ opening, opacity, arrival }) => {
  const lid = `translate(0 ${-100 * opening}) rotate(${-10 * opening} 230 93)`;
  return (
    <svg width={460} height={370} viewBox="0 0 460 370" aria-label="Ballot box" style={{ position: "absolute", left: BOX.x, top: BOX.y, overflow: "visible", opacity, transformOrigin: "230px 83px", transform: `translateY(${(1 - arrival) * 13}px) scale(${mix(0.86, 1, arrival)})`, filter: "drop-shadow(0px 16px 18px rgba(23,40,51,0.06))" }}>
      <rect x={59} y={105} width={342} height={214} rx={7} fill={C.white} stroke={C.graphite} strokeWidth={2} transform={`translate(0 ${opening * 60})`} />
      <rect x={43} y={59} width={374} height={51} rx={6} fill="#FBFAF5" stroke={C.graphite} strokeWidth={2} transform={lid} />
      <rect x={151} y={79} width={158} height={8} rx={4} fill={C.graphite} transform={lid} />
      <path d="M59 113 L59 306 L81 319" fill="none" stroke={C.gray} strokeWidth={2} transform={`translate(${-86 * opening} ${38 * opening}) rotate(${-24 * opening} 59 113)`} />
      <path d="M401 113 L401 306 L379 319" fill="none" stroke={C.gray} strokeWidth={2} transform={`translate(${86 * opening} ${38 * opening}) rotate(${24 * opening} 401 113)`} />
      <rect x={143} y={161} width={174} height={105} rx={3} fill="none" stroke={C.gray} strokeWidth={1.5} transform={`translate(0 ${opening * 88})`} />
      <path d="M82 320 H378" fill="none" stroke={C.graphite} strokeWidth={2} transform={`translate(0 ${opening * 98})`} />
      <path d="M111 334 H349" fill="none" stroke={C.gray} strokeWidth={1.5} transform={`translate(0 ${opening * 118})`} />
    </svg>
  );
};

const PeerLedger: React.FC<{ peer: typeof peers[number]; i: number; enter: number; active: number; ink: number; landing: number; rowFocus: number }> = ({ peer, i, enter, active, ink, landing, rowFocus }) => (
  <div style={{ position: "absolute", left: peer.x, top: peer.y, width: PW, height: PH, boxSizing: "border-box", border: "1px solid rgba(23,40,51,0.22)", borderRadius: 13, background: "rgba(255,255,255,0.87)", boxShadow: "0 9px 26px rgba(23,40,51,0.045)", opacity: enter, transform: `translateY(${mix(20, 0, enter)}px) scale(${mix(0.975, 1, enter)})`, transformOrigin: "50% 50%" }}>
    <div style={{ position: "absolute", left: 27, top: 18, color: C.graphite, fontFamily: UI, fontSize: 28, fontWeight: 400, letterSpacing: "-0.7px" }}>Ledger</div>
    <div style={{ position: "absolute", right: 27, top: 26, fontFamily: MONO, fontSize: 13, fontWeight: 500, letterSpacing: "0.8px", color: C.teal, opacity: active }}>{"COPY"}</div>
    <div style={{ position: "absolute", left: 28, right: 28, top: 57, height: 1, background: "rgba(23,40,51,0.13)" }} />
    {ROW_Y.map((y, row) => (
      <div key={row} style={{ position: "absolute", left: 28, top: y - 1, opacity: row === 0 && i === 2 ? 1 - landing : row === 1 ? mix(0.76, 0.94, rowFocus) : 0.68 }}>
        <RecordFace active={row === 0 ? active : 0} ink={ink} />
      </div>
    ))}
  </div>
);

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cueAt = (index: number, fallback: number) => {
    const explicit = cues.find(c => c.wordIndex === index || c.index === index);
    const positional = cues[index];
    const cue = explicit || positional;
    return cue && Number.isFinite(cue.startFrame) ? cue.startFrame : fallback;
  };
  const imagine = cueAt(0, 10);
  const establish = cueAt(1, 66);
  const election = cueAt(2, 77);
  const noQueue = cueAt(5, 132);
  const stand = cueAt(8, 163);
  const line = cueAt(10, 186);
  const noBox = cueAt(12, 214);
  const ballot = cueAt(14, 238);
  const boxes = cueAt(15, 256);
  const every = cueAt(17, 340);
  const vote = cueAt(18, 364);
  const permanent = cueAt(20, 397);
  const recorded = cueAt(21, 428);
  const sounds = cueAt(22, 544);
  const perfect = cueAt(23, 561);
  const right = cueAt(24, 581);
  const transparent = cueAt(26, 655);
  const decentralized = cueAt(28, 750);
  const nobody = cueAt(29, 825);
  const secretly = cueAt(31, 871);
  const change = cueAt(32, 900);
  const votes = cueAt(34, 930);
  const arrivalAt = Math.max(2, imagine - 8);
  const arrival = spring({ frame: frame - arrivalAt, fps, config: { stiffness: 160, damping: 25.3, mass: 1 }, durationInFrames: 28, overshootClamping: true });
  const emblemOpacity = interpolate(frame, [arrivalAt, arrivalAt + 7], [0, 1], clamp);
  const open = smooth(frame, noBox, boxes + 50);
  const boxOpacity = emblemOpacity * (1 - smooth(frame, ballot + 12, boxes + 74));
  const panelEnter = spring({ frame: frame - (ballot + 14), fps, config: { stiffness: 160, damping: 25.3, mass: 1 }, durationInFrames: 66, overshootClamping: true });
  const registered = smooth(frame, permanent, recorded + 4);
  const landing = smooth(frame, every, vote + 18);
  const flight = smooth(frame, noBox, ballot + 14);
  const tileMid = { x: 800 - TW / 2, y: 358 };
  const tileStart = { x: 252, y: 526 };
  const tileX = mix(mix(tileStart.x, tileMid.x, flight), TARGET.x, landing);
  const tileY = mix(mix(tileStart.y, tileMid.y, flight), TARGET.y, landing);
  const inspection = smooth(frame, transparent, transparent + 30);
  const ink = mix(0.84, 1, inspection);
  const matchAt = Math.max(977, durationInFrames - 26);
  const match = smooth(frame, matchAt, Math.max(matchAt + 1, durationInFrames - 1));

  const MACRO: View = { z: 1.82, cx: 800, cy: 503 };
  const PHYSICAL: View = { z: 1.13, cx: 738, cy: 520 };
  const LANDED: View = { z: 1.56, cx: 870, cy: 669 };
  const REGISTERED: View = { z: 1.91, cx: 870, cy: 673 };
  const INSPECTED: View = { z: 1.91, cx: 915, cy: 682 };
  const WIDE: View = { z: 1, cx: 800, cy: 550 };
  let camera = mixView({ z: 1.98, cx: 800, cy: 507 }, MACRO, arrival);
  if (frame >= establish) camera = mixView(MACRO, PHYSICAL, smooth(frame, establish, election + 36));
  if (frame >= every) camera = mixView(PHYSICAL, LANDED, landing);
  if (frame >= permanent) camera = mixView(LANDED, REGISTERED, smooth(frame, permanent, recorded + 4));
  if (frame >= transparent) camera = mixView(REGISTERED, INSPECTED, inspection);
  if (frame >= decentralized) camera = mixView(INSPECTED, WIDE, smooth(frame, decentralized, decentralized + 42));
  // The final transform is a continuation of this same rig, not a new shot.
  const z = mix(camera.z, 0.96, match);
  const cameraTx = mix(800 - camera.cx * camera.z, 444 - 870 * 0.96, match);
  const cameraTy = mix(525 - camera.cy * camera.z, 543 - 681 * 0.96, match);
  const cueWords = [
    { text: "Sounds", at: sounds },
    { text: "perfect,", at: perfect },
    { text: "right?", at: right },
  ];
  const questionOut = 1 - smooth(frame, right + 16, transparent - 20);
  const peerEvidence = smooth(frame, nobody, nobody + 22);
  const scrutiny = smooth(frame, secretly, secretly + 28) * (1 - smooth(frame, votes + 34, votes + 46));
  const scrutinySettle = 1 - smooth(frame, change, votes + 12);
  const screenScale = Math.min(width / 1920, height / 1080);

  return (
    <AbsoluteFill style={{ backgroundColor: C.ivory, color: C.graphite, fontFamily: UI, overflow: "hidden" }}>
      <div style={{ position: "absolute", width: 1920, height: 1080, left: (width - 1920 * screenScale) / 2, top: (height - 1080 * screenScale) / 2, transform: `scale(${screenScale})`, transformOrigin: "0 0", overflow: "hidden" }}>
        <AbsoluteFill style={{ background: "radial-gradient(ellipse at 56% 41%, rgba(255,255,255,0.78) 0%, rgba(255,255,255,0.15) 53%, rgba(230,227,216,0.22) 100%)" }} />

        {/* Screen-locked documentary furniture. */}
        <div style={{ position: "absolute", inset: 0, zIndex: 20, pointerEvents: "none", opacity: 1 - 0.3 * match }}>
          <mg.Heading kicker="THE OPENING PROMISE" title="An election, recorded" frameAt={2} style={{ position: "absolute", left: 100, top: 56, maxWidth: 1100, color: C.graphite, fontFamily: "'Inter Tight', 'Inter', 'Arial', sans-serif", fontSize: 52, fontWeight: 600, lineHeight: 1.08, letterSpacing: "-1.5px", whiteSpace: "nowrap" }} />
        </div>

        <div style={{ position: "absolute", left: 160, top: 170, width: 1600, height: 890, overflow: "hidden", borderRadius: 19 }}>
          {/* One continuous world-space camera. Transform maps world points into this 1600 x 890 stage. */}
          <div style={{ position: "absolute", left: 0, top: 0, width: 1600, height: 890, transform: `translate(${cameraTx}px, ${cameraTy}px) scale(${z})`, transformOrigin: "0 0" }}>
            <div style={{ position: "absolute", inset: 0, boxSizing: "border-box", border: "1px solid rgba(23,40,51,0.11)", borderRadius: 18, backgroundColor: "rgba(255,255,255,0.27)", backgroundImage: "radial-gradient(circle, rgba(23,40,51,0.11) 0.85px, transparent 1px)", backgroundSize: "40px 40px", opacity: mix(0.36, 1, panelEnter) }} />
            <div style={{ position: "absolute", left: 30, right: 30, top: 28, height: 1, background: "rgba(23,40,51,0.08)" }} />
            <div style={{ position: "absolute", left: 30, right: 30, bottom: 28, height: 1, background: "rgba(23,40,51,0.08)" }} />

            {/* Peer-to-peer topology: equal lines, no privileged center or hub. */}
            <svg width={1600} height={890} viewBox="0 0 1600 890" style={{ position: "absolute", inset: 0, overflow: "visible", opacity: panelEnter }} aria-label="Five equal linked ledger copies">
              {EDGES.map(([a, b], i) => {
                const p = { x: peers[a].x + PW / 2, y: peers[a].y + PH / 2 };
                const q = { x: peers[b].x + PW / 2, y: peers[b].y + PH / 2 };
                return <line key={`edge-${i}`} x1={p.x} y1={p.y} x2={q.x} y2={q.y} stroke={C.graphite} strokeWidth={1.15} opacity={mix(0.16, 0.25, smooth(frame, decentralized, decentralized + 42))} />;
              })}
              {EDGES.map(([a, b], i) => {
                const p = { x: peers[a].x + PW / 2, y: peers[a].y + PH / 2 };
                const q = { x: peers[b].x + PW / 2, y: peers[b].y + PH / 2 };
                const len = Math.hypot(q.x - p.x, q.y - p.y);
                const starts = [recorded, decentralized + 3];
                return starts.map((start, j) => {
                  const t = interpolate(frame, [start, start + 40], [0, 1], clamp);
                  const u = (i + j) % 2 === 0 ? t : 1 - t;
                  const alpha = Math.sin(Math.PI * t) * 0.68;
                  return <line key={`packet-${i}-${j}`} x1={mix(p.x, q.x, u) - (q.x - p.x) / len * 7} y1={mix(p.y, q.y, u) - (q.y - p.y) / len * 7} x2={mix(p.x, q.x, u) + (q.x - p.x) / len * 7} y2={mix(p.y, q.y, u) + (q.y - p.y) / len * 7} stroke={C.teal} strokeWidth={2} strokeLinecap="round" opacity={alpha} />;
                });
              })}
            </svg>

            {peers.map((peer, i) => <PeerLedger key={i} peer={peer} i={i} enter={panelEnter} active={i === 2 ? registered : registered} ink={ink} landing={landing} rowFocus={inspection} />)}

            {/* Restrained documentary labels; no invented voter data or numerical claims. */}
            <div style={{ position: "absolute", left: peers[2].x + 8, top: peers[2].y - 42, display: "flex", alignItems: "center", gap: 9, fontFamily: MONO, fontSize: 15, fontWeight: 500, color: C.teal, letterSpacing: "1.1px", opacity: smooth(frame, recorded, recorded + 20) * (1 - smooth(frame, sounds, sounds + 10)) }}>
              <div style={{ width: 6, height: 6, background: C.teal }} />RECORDED
            </div>
            <div style={{ position: "absolute", left: peers[2].x + 5, top: peers[2].y - 57, display: "flex", gap: 7, alignItems: "baseline", whiteSpace: "nowrap", color: C.graphite, fontSize: 30, fontWeight: 400, letterSpacing: "-0.7px", opacity: questionOut }}>
              {cueWords.map(w => <span key={w.text} style={{ display: "inline-block", opacity: smooth(frame, w.at, w.at + 6), transform: `translateY(${mix(5, 0, smooth(frame, w.at, w.at + 8))}px)` }}>{w.text}</span>)}
            </div>

            <BallotBox opening={open} opacity={boxOpacity} arrival={arrival} />

            {/* The two trailing tickets disappear. The leading ticket is never replaced or unmounted. */}
            {[0, 1].map((i) => {
              const starts = [noQueue, stand];
              const ends = [line, line + 23];
              const gone = smooth(frame, starts[i], ends[i]);
              const show = smooth(frame, establish + 6 + i * 3, election + 36);
              return (
                <div key={`ticket-${i}`} style={{ position: "absolute", left: 252, top: 616 + i * 82, opacity: show * (1 - gone), transform: `translate(${-52 * gone}px, ${mix(10, 0, show)}px) rotate(${-3 * gone}deg)`, boxShadow: "0 5px 12px rgba(23,40,51,0.04)", borderRadius: 5 }}>
                  <RecordFace active={0} ticket />
                </div>
              );
            })}
            <div style={{ position: "absolute", left: tileX, top: tileY, width: TW, height: TH, opacity: smooth(frame, establish + 4, election + 34), transform: `translateY(${-34 * Math.sin(Math.PI * flight) * (1 - landing)}px)`, boxShadow: `0 ${mix(9, 0, landing)}px ${mix(20, 0, landing)}px rgba(23,40,51,${mix(0.1, 0, landing)})`, borderRadius: 5, zIndex: 6 }}>
              <RecordFace active={1} ink={ink} ticket />
            </div>

            {/* Copies stay intact while one entry is inspected; coral means scrutiny, not fraud. */}
            {peers.map((p, i) => <div key={`evidence-${i}`} style={{ position: "absolute", left: p.x + 29, top: p.y + ROW_Y[0], width: TW, height: TH, borderRadius: 5, boxSizing: "border-box", border: "1px solid rgba(22,125,141,0.32)", opacity: peerEvidence * 0.7, pointerEvents: "none", zIndex: 7 }} />)}
            <div style={{ position: "absolute", left: TARGET.x - 10, top: TARGET.y - 9, width: TW + 20, height: TH + 18, opacity: scrutiny * mix(0.84, 1, scrutinySettle), zIndex: 8, color: C.coral, pointerEvents: "none" }}>
              <mg.FocusFrame color={C.coral} frameAt={secretly} style={{ position: "absolute", inset: 0, width: TW + 20, height: TH + 18, color: C.coral, borderColor: C.coral, background: "transparent" }} />
            </div>
          </div>
        </div>

        {/* The full ledger travels left as a unit. A single storage-card perimeter enters;
            no right-hand argument or new claim is exposed in this shot. */}
        <div style={{ position: "absolute", left: mix(129, 104, match), top: 232, width: 918, height: 746, borderRadius: 21, border: "1px solid rgba(23,40,51,0.24)", boxSizing: "border-box", opacity: match * 0.8, pointerEvents: "none", zIndex: 12, background: "transparent" }} />
      </div>
    </AbsoluteFill>
  );
};

import React from "react";
import { AbsoluteFill, Sequence, useCurrentFrame, useVideoConfig, interpolate, spring, Easing, random } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { index?: number; wordIndex?: number; startFrame: number; endFrame?: number; word?: string; text?: string };
type ShotProps = { wordCues?: WordCue[] };

const C = {
  ivory: "#F3F1E9",
  white: "#FFFFFF",
  graphite: "#172833",
  gray: "#9AA8AD",
  teal: "#167D8D",
  cobalt: "#365FDB",
  coral: "#EE735E"
};
const sans = '"Inter", Arial, sans-serif';
const tight = '"Inter Tight", "Inter", Arial, sans-serif';
const mono = '"IBM Plex Mono", monospace';
const MgHeading = mg.Heading as React.ComponentType<any>;
const MgFocusFrame = mg.FocusFrame as React.ComponentType<any>;

const RecordTile = () => {
  const corners = [
    { left: 12, top: 12, borderLeft: "2px solid", borderTop: "2px solid" },
    { right: 12, top: 12, borderRight: "2px solid", borderTop: "2px solid" },
    { left: 12, bottom: 12, borderLeft: "2px solid", borderBottom: "2px solid" },
    { right: 12, bottom: 12, borderRight: "2px solid", borderBottom: "2px solid" }
  ];
  return (
    <div style={{ position: "absolute", inset: 0, boxSizing: "border-box", background: C.teal, color: C.white, border: "1px solid rgba(255,255,255,0.4)", borderRadius: 12, boxShadow: "0 12px 28px rgba(22,125,141,0.18)" }}>
      {corners.map((corner, i) => <div key={i} style={{ position: "absolute", width: 11, height: 11, borderColor: "rgba(255,255,255,0.65)", ...corner }} />)}
      <div style={{ position: "absolute", left: 36, top: 26, fontFamily: mono, fontSize: 18, fontWeight: 500, letterSpacing: "0.12em" }}>VOTE RECORD</div>
      <div style={{ position: "absolute", left: 36, top: 68, width: 176, height: 2, background: "rgba(255,255,255,0.7)" }} />
      <div style={{ position: "absolute", left: 36, top: 81, width: 126, height: 2, background: "rgba(255,255,255,0.36)" }} />
      <div style={{ position: "absolute", right: 38, top: 66, width: 28, height: 17, display: "flex", gap: 4 }}>
        {[2, 4, 2, 6, 2].map((w, i) => <div key={i} style={{ width: w, height: "100%", background: "rgba(255,255,255,0.65)" }} />)}
      </div>
    </div>
  );
};

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const f = Math.min(frame, durationInFrames - 1);
  const cueFrame = (id: number, fallback: number) => {
    const indexed = cues.find((c) => c.wordIndex === id || c.index === id);
    if (indexed && Number.isFinite(indexed.startFrame)) return indexed.startFrame;
    const local = cues.length === 39 ? cues[id - 35] : undefined;
    return local && Number.isFinite(local.startFrame) ? local.startFrame : fallback;
  };
  const ramp = (start: number, end: number) => interpolate(f, [start, Math.max(start + 1, end)], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.cubic) });
  const blockchainAt = cueFrame(43, 92);
  const storingAt = cueFrame(51, 348);
  const trackAt = cueFrame(54, 449);
  const identityAt = cueFrame(58, 538);
  const castingAt = cueFrame(61, 595);
  const forcedAt = cueFrame(66, 776);
