import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; startFrame?: number; word?: string; text?: string };
type ShotProps = { wordCues?: WordCue[] };
type Point = { x: number; y: number };
type Branch = { id: string; end: Point; c1: Point; c2: Point; delay: number };

const C = { paper: "#F3F1E9", white: "#FFFFFF", ink: "#172833", gray: "#9AA8AD", teal: "#167D8D", cobalt: "#365FDB", coral: "#EE735E" };
const FONT = "Inter, Arial, sans-serif";
const MONO = "IBM Plex Mono, monospace";
const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
const smooth = { ...clamp, easing: Easing.inOut(Easing.cubic) };
const origin: Point = { x: 720, y: 438 };
const branches: Branch[] = [
  { id: "A", end: { x: 345, y: 180 }, c1: { x: 640, y: 250 }, c2: { x: 470, y: 180 }, delay: 0 },
  { id: "B", end: { x: 1095, y: 180 }, c1: { x: 810, y: 245 }, c2: { x: 960, y: 180 }, delay: 0 },
  { id: "C", end: { x: 345, y: 700 }, c1: { x: 635, y: 630 }, c2: { x: 470, y: 700 }, delay: 7 },
  { id: "D", end: { x: 1095, y: 700 }, c1: { x: 805, y: 635 }, c2: { x: 965, y: 700 }, delay: 11 }
];

const bezier = (branch: Branch, t: number): Point => {
  const u = 1 - t;
  return {
    x: u * u * u * origin.x + 3 * u * u * t * branch.c1.x + 3 * u * t * t * branch.c2.x + t * t * t * branch.end.x,
    y: u * u * u * origin.y + 3 * u * u * t * branch.c1.y + 3 * u * t * t * branch.c2.y + t * t * t * branch.end.y
  };
};

const branchPath = (b: Branch) => `M ${origin.x} ${origin.y} C ${b.c1.x} ${b.c1.y}, ${b.c2.x} ${b.c2.y}, ${b.end.x} ${b.end.y}`;

const VoteTile: React.FC<{ width?: number; height?: number; opacity?: number }> = ({ width = 292, height = 84, opacity = 1 }) => (
  <div style={{ width, height, position: "relative", boxSizing: "border-box", borderRadius: 12, background: "#E5F2F1", border: "1px solid rgba(22,125,141,0.36)", display: "flex", alignItems: "center", justifyContent: "center", color: C.teal, fontFamily: FONT, fontSize: 30, fontWeight: 500, opacity }}>
