    <div style={{ position: "absolute", top: 0, right: 0, width: 18, height: 18, background: C.teal, clipPath: "polygon(0 0, 100% 0, 100% 100%)", borderTopRightRadius: 10 }} />
    <div style={{ position: "absolute", bottom: 10, left: 13, width: 22, height: 3, borderRadius: 2, background: C.teal, opacity: 0.52 }} />
  </div>
);

export const GeneratedShot: React.FC<ShotProps> = (props) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const f = Math.min(frame, durationInFrames - 1, 1028);
  const cue = (index: number, fallback: number): number => {
    const explicit = cues.find((c) => c.wordIndex === index || c.index === index);
    const ordered = cues.length === 42 ? cues[index - 74] : cues.length > 115 ? cues[index] : undefined;
    const value = (explicit || ordered)?.startFrame;
    return typeof value === "number" && Number.isFinite(value) ? value : fallback;
  };
  const obvious = cue(78, 47);
  const once = cue(80, 155);
  const vote = cue(82, 193);
  const recorded = cue(84, 222);
  const blockchain = cue(87, 264);
  const changing = cue(88, 316);
  const difficult = cue(93, 414);
  const everyone = cue(94, 474);
  const independently = cue(96, 511);
  const verify = cue(97, 553);
  const chainCheck = cue(100, 594);
  const tampered = cue(103, 655);
  const but = cue(105, 735);
  const problem = cue(108, 759);
  const an = cue(109, 827);
  const election = cue(110, 835);
  const isnt = cue(111, 867);
  const database = cue(114, 917);
  const lastProblem = cue(115, 951);
  const ramp = (start: number, end: number) => interpolate(f, [start, Math.max(start + 1, end)], [0, 1], smooth);
  const arrival = spring({ frame: Math.max(0, f - 2), fps, config: { stiffness: 160, damping: 26, mass: 1 }, durationInFrames: 28 });
  const meshSpring = spring({ frame: Math.max(0, f - obvious), fps, config: { stiffness: 160, damping: 14, mass: 1 } });
  const meshOpacity = ramp(obvious, obvious + 26);
  const settle = ramp(vote, recorded + 29);
  const chainResolve = ramp(recorded, blockchain + 34);
  const shellOpacity = 0.24 * (1 - ramp(2, 26));
  const scrutiny = ramp(changing, changing + 20) * (1 - ramp(difficult + 26, everyone - 10));
  const checksStarted = ramp(everyone, everyone + 20);
  const boundaryOpacity = ramp(but, problem + 23);
  const identityOpacity = ramp(election, isnt + 25);
  const boundaryLabel = ramp(database, lastProblem + 28);
  const follow = bezier(branches[1], interpolate(f, [everyone, verify + 29], [0, 1], smooth));

  let zoom = 1.4;
  let targetX = origin.x;
  let targetY = origin.y;
  if (f >= obvious && f < once) {
    zoom = interpolate(f, [obvious, obvious + 72], [1.4, 1.18], smooth);
  } else if (f >= once && f < changing) {
    zoom = interpolate(f, [once, blockchain + 34], [1.18, 1.5], smooth);
  } else if (f >= changing && f < everyone) {
    zoom = 1.5;
    const inspect = ramp(changing, difficult + 26);
    targetX = origin.x + 22 * inspect;
    targetY = origin.y - 28 * inspect;
  } else if (f >= everyone && f < chainCheck) {
    zoom = interpolate(f, [everyone, verify + 29], [1.5, 1.24], smooth);
    const release = ramp(everyone, everyone + 20);
    targetX = follow.x + 22 * (1 - release);
    targetY = follow.y - 28 * (1 - release);
  } else if (f >= chainCheck && f < but) {
    const macro = ramp(chainCheck, tampered + 54);
    zoom = 1.24 - 0.14 * macro;
    targetX = 1095 + (720 - 1095) * macro;
    targetY = 180 + (438 - 180) * macro;
  } else if (f >= but && f < an) {
    const firstPull = ramp(but, problem + 23);
    zoom = 1.1 - 0.035 * firstPull;
    targetX = 720 + 38 * firstPull;
    targetY = 438;
  } else if (f >= an) {
    const finalPull = ramp(an, lastProblem + 28);
    zoom = 1.065 - 0.065 * finalPull;
    targetX = 758 + 72 * finalPull;
    targetY = 438 + 2 * finalPull;
  }

  const routeFocus = ramp(everyone, everyone + 45);
  const boundaryFocus = ramp(but, problem + 23);
  const relationFocus = ramp(isnt, lastProblem + 28);
  const focusA = { x: 546, y: 362, w: 348, h: 152 };
  const focusB = { x: 177, y: 113, w: 1086, h: 654 };
  const focusC = { x: 68, y: 57, w: 1284, h: 728 };
  const focusD = { x: 1264, y: 342, w: 378, h: 205 };
  const blend = (a: number, b: number, t: number) => a + (b - a) * t;
  const focusBox = {
    x: blend(blend(blend(focusA.x, focusB.x, routeFocus), focusC.x, boundaryFocus), focusD.x, relationFocus),
    y: blend(blend(blend(focusA.y, focusB.y, routeFocus), focusC.y, boundaryFocus), focusD.y, relationFocus),
    w: blend(blend(blend(focusA.w, focusB.w, routeFocus), focusC.w, boundaryFocus), focusD.w, relationFocus),
    h: blend(blend(blend(focusA.h, focusB.h, routeFocus), focusC.h, boundaryFocus), focusD.h, relationFocus)
  };
  const FocusFrame = mg.FocusFrame as React.ComponentType<any>;
  const Heading = mg.Heading as React.ComponentType<any>;
  const artScale = Math.min(width / 1920, height / 1080);

  return (
    <AbsoluteFill style={{ backgroundColor: C.paper, overflow: "hidden", color: C.ink, fontFamily: FONT }}>
      <div style={{ position: "absolute", width: 1920, height: 1080, left: (width - 1920 * artScale) / 2, top: (height - 1080 * artScale) / 2, transform: `scale(${artScale})`, transformOrigin: "top left" }}>
        <div style={{ position: "absolute", inset: 0, background: "radial-gradient(ellipse at 49% 45%, rgba(255,255,255,0.82) 0%, rgba(255,255,255,0.15) 65%, transparent 100%)" }} />
        <div style={{ position: "absolute", left: 130, top: 190, width: 1660, height: 880, overflow: "hidden", borderRadius: 26, background: "rgba(255,255,255,0.31)", border: "1px solid rgba(23,40,51,0.09)", boxSizing: "border-box" }}>
          <div style={{ position: "absolute", inset: 0, opacity: 0.24, backgroundImage: "radial-gradient(circle, rgba(154,168,173,0.72) 0.85px, transparent 1px)", backgroundSize: "28px 28px" }} />
          <div style={{ position: "absolute", width: 1660, height: 880, transformOrigin: "0 0", transform: `translate(${830 - targetX * zoom}px, ${440 - targetY * zoom}px) scale(${zoom})` }}>
            {[450, 790].map((x, i) => (
              <div key={`shell-${i}`} style={{ position: "absolute", left: x, top: 293, width: 300, height: 272, border: "1px solid rgba(23,40,51,0.3)", borderRadius: 22, background: "rgba(255,255,255,0.3)", opacity: shellOpacity, transform: `translateY(${-10 * ramp(2, 26)}px)` }} />
            ))}

            <div style={{ position: "absolute", left: 80, top: 69, width: 1260, height: 704, borderRadius: 26, border: "1.5px solid rgba(23,40,51,0.32)", background: "rgba(255,255,255,0.08)", opacity: boundaryOpacity }} />
            <div style={{ position: "absolute", left: 103, top: 752, padding: "4px 16px", background: C.paper, color: C.ink, fontSize: 30, lineHeight: "36px", opacity: boundaryLabel }}>a database problem</div>

            <svg width={1660} height={880} viewBox="0 0 1660 880" style={{ position: "absolute", inset: 0, overflow: "visible" }} aria-hidden="true">
