import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; startFrame?: number; endFrame?: number; word?: string; text?: string };
type ShotProps = { wordCues?: WordCue[] };

const C = { ivory: "#F3F1E9", white: "#FFFFFF", ink: "#172833", gray: "#9AA8AD", teal: "#167D8D", cobalt: "#365FDB", coral: "#EE735E", inside: "#FCF8F1" };
const sans = "Inter, Arial, sans-serif";
const tight = "Inter Tight, Inter, Arial, sans-serif";
const mono = "IBM Plex Mono, monospace";
const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
const limit = (v: number) => Math.max(0, Math.min(1, v));
const mix = (a: number, b: number, p: number) => a + (b - a) * p;
const ease = (p: number) => { const t = limit(p); return t * t * (3 - 2 * t); };
const transition = (f: number, a: number, b: number) => ease(interpolate(f, [a, Math.max(a + 1, b)], [0, 1], clamp));

const Tile = ({ label, color, left, top, opacity = 1 }: { label: string; color: string; left: number; top: number; opacity?: number }) => (
  <div style={{ position: "absolute", left, top, width: 204, height: 88, opacity, boxSizing: "border-box", background: C.white, border: "1px solid " + color, borderLeft: "7px solid " + color, borderRadius: 9, boxShadow: "0 9px 20px rgba(23,40,51,0.06)", display: "flex", alignItems: "center", paddingLeft: 22, fontFamily: sans, fontSize: 28, color, whiteSpace: "nowrap" }}>{label}</div>
);

