const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
const cueWords = [
  "So", "we", "have", "to", "somehow", "prove", "that", "a", "legitimate", "person", "cast", "a", "legitimate", "vote,", "while", "simultaneously", "making", "sure", "nobody", "can", "figure", "out", "which", "vote", "belongs", "to", "that", "person.", "That's", "possible", "in", "theory", "using", "advanced", "cryptography,", "like", "zero", "knowledge", "proofs", "and", "anonymous", "credentials.",
];
const cueFrames = [0, 7, 15, 28, 37, 61, 110, 127, 132, 160, 187, 205, 213, 238, 295, 307, 358, 381, 415, 441, 457, 475, 504, 517, 540, 568, 574, 586, 651, 666, 688, 694, 716, 730, 762, 829, 850, 868, 889, 913, 939, 968];
const cleanWord = (v: string) => v.toLowerCase().replace(/[^a-z0-9]/g, "");

const CueWord: React.FC<{ text: string; at: number; frame: number; fps: number; color?: string; lift?: number }> = ({ text, at, frame, fps, color, lift = 8 }) => {
  const enter = spring({ frame: Math.max(0, frame - at), fps, config: { stiffness: 160, damping: 14, mass: 0.75 } });
  const opacity = interpolate(frame, [at, at + 7], [0, 1], clamp);
  return <span style={{ display: "inline-block", whiteSpace: "pre", opacity, color, transform: `translateY(${(1 - enter) * lift}px)` }}>{text}</span>;
};

