export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];

  const t = (wordIndex: number) => {
    const i = wordIndex - 225;
    const indexed = cues.find((cue) => {
      const raw = cue.wordIndex ?? cue.index ?? cue.id;
      return raw === wordIndex || raw === `W${wordIndex}`;
    });
    if (indexed && typeof indexed.startFrame === "number") return indexed.startFrame;
    if (cues.length === cueWords.length && typeof cues[i]?.startFrame === "number") return cues[i].startFrame as number;
    const positional = cues[wordIndex];
    if (positional && typeof positional.startFrame === "number" && cleanWord(positional.word || positional.text || "") === cleanWord(cueWords[i])) return positional.startFrame;
    const candidates = cues.filter((cue) => typeof cue.startFrame === "number" && cleanWord(cue.word || cue.text || "") === cleanWord(cueWords[i]));
    if (candidates.length > 0) return candidates.reduce((a, b) => Math.abs((a.startFrame as number) - cueFrames[i]) < Math.abs((b.startFrame as number) - cueFrames[i]) ? a : b).startFrame as number;
    return cueFrames[i];
  };
  const end = (wordIndex: number, fallback: number) => {
    const i = wordIndex - 225;
    const cue = cues.find((c) => (c.wordIndex ?? c.index ?? c.id) === wordIndex || (c.wordIndex ?? c.index ?? c.id) === `W${wordIndex}`) || (cues.length === cueWords.length ? cues[i] : undefined);
    return typeof cue?.endFrame === "number" ? cue.endFrame : fallback + t(wordIndex) - cueFrames[i];
  };
  const ease = (a: number, b: number) => interpolate(frame, [a, Math.max(a + 1, b)], [0, 1], { ...clamp, easing: Easing.inOut(Easing.cubic) });
  const mix = (a: number, b: number, p: number) => a + (b - a) * p;

  const cameraKeys = [
