    { f: t(231), z: 1, x: 0, y: 0 },
    { f: end(234, 184), z: 1.12, x: -424, y: -172 },
    { f: t(235), z: 1.12, x: -424, y: -172 },
    { f: end(238, 254), z: 1.12, x: -424, y: 66 },
