const tight = 'Inter Tight, Inter, Arial, sans-serif';
const mono = 'IBM Plex Mono, monospace';
const clamp = { extrapolateLeft: 'clamp' as const, extrapolateRight: 'clamp' as const };
const ease = Easing.inOut(Easing.cubic);
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const mixPoint = (a: Point, b: Point, t: number): Point => ({ x: lerp(a.x, b.x, t), y: lerp(a.y, b.y, t) });
const progress = (f: number, a: number, b: number) => interpolate(f, [a, b], [0, 1], { ...clamp, easing: ease });
const cubic = (c: Curve, t: number): Point => {
  const s = 1 - t;
  return { x: s*s*s*c[0].x + 3*s*s*t*c[1].x + 3*s*t*t*c[2].x + t*t*t*c[3].x, y: s*s*s*c[0].y + 3*s*s*t*c[1].y + 3*s*t*t*c[2].y + t*t*t*c[3].y };
};
const mixCurve = (a: Curve, b: Curve, t: number): Curve => a.map((p, i) => mixPoint(p, b[i], t)) as Curve;
const flatCurve = (c: Curve): Curve => c.map((p) => ({ x: p.x, y: 675 })) as Curve;

