const Rule: React.FC<{ a: Point; b: Point; color?: string; thickness?: number; opacity?: number }> = ({ a, b, color = C.gray, thickness = 1.5, opacity = 1 }) => {
  const dx = b.x-a.x;
  const dy = b.y-a.y;
  return <div style={{ position: 'absolute', left: a.x, top: a.y, width: Math.sqrt(dx*dx+dy*dy), height: thickness, background: color, opacity, transformOrigin: '0 50%', transform: `rotate(${Math.atan2(dy, dx)}rad)`, borderRadius: thickness, pointerEvents: 'none' }} />;
};

const Conduit: React.FC<{ curve: Curve; color: string; reveal?: number; opacity?: number; width?: number }> = ({ curve, color, reveal = 1, opacity = 1, width = 3 }) => {
  const steps = 52;
  return <div style={{ position: 'absolute', inset: 0, opacity, pointerEvents: 'none' }}>
    {Array.from({ length: steps }, (_, i) => {
      const a = cubic(curve, i/steps);
      const b = cubic(curve, Math.min((i+1)/steps, reveal));
      if (i/steps >= reveal) return null;
      return <Rule key={i} a={a} b={b} color={color} thickness={width} />;
    })}
  </div>;
};

