  const cue = (id: number, fallback: number) => {
    const exact = cues.find((c) => c.wordIndex === id || c.index === id);
    const local = cues.length === 50 ? cues[id-267] : undefined;
    const value = exact?.startFrame ?? local?.startFrame;
    return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
  };
  const nowAt = cue(268, 4);
  const ourAt = cue(269, 32);
  const systemAt = cue(273, 110);
  const openAt = cue(274, 145);
  const cryptoAt = cue(279, 272);
