  const separationEnd = separateAt+32;
  const personAt = cue(309, 968);
  const controlAt = cue(314, 1039);
  const voteEnd = cue(316, 1061)+20;
  const enter = spring({ frame: Math.max(0, f-2), fps, config: { stiffness: 160, damping: 14, mass: .9 }, durationInFrames: 28 });
  const enterOpacity = progress(f, 2, 9);
  const unfold = progress(f, openAt, cryptoEnd);
