  const cameraFrames = [2, 30, ourAt, systemAt+25, openAt, cue(278,228), cryptoEnd, workAt, flawlessAt+40, millionAt, peopleEnd, beyondAt, biggerAt, coercionAt+3, stationAt, stationEnd, inspectAt, separationEnd, controlAt, voteEnd, 1082];
