              <div style={{position:'absolute',left:338,top:253,width:367,height:325,borderRadius:20,border:'1px solid rgba(22,125,141,.19)',background:'rgba(22,125,141,.025)'}} />
              <div style={{position:'absolute',left:94,top:590,fontSize:26,color:C.cobalt,opacity:progress(f,stationEnd-20,stationEnd+15)}}>identity evidence</div>
