              <div style={{position:'absolute',left:2744,top:286,width:92,height:510,background:'rgba(23,40,51,.07)',filter:'blur(11px)',transform:`translate(20px, 19px) scaleY(${wallT})`,transformOrigin:'50% 0'}} />
              <div style={{position:'absolute',left:2750,top:290,width:84,height:514,background:'#D2D1C8',clipPath:'polygon(0 0, 73% 0, 100% 6%, 100% 100%, 27% 100%, 0 94%)',transform:`scaleY(${wallT})`,transformOrigin:'50% 0'}} />
              <div style={{position:'absolute',left:2726,top:276,width:86,height:508,boxSizing:'border-box',background:'#F1EEDF',border:'1.5px solid #9BA59F',borderRadius:2,transform:`scaleY(${wallT})`,transformOrigin:'50% 0',boxShadow:'inset 8px 0 0 rgba(255,255,255,.62)'}} />
              <div style={{position:'absolute',left:2759,top:337,width:20,height:385,borderLeft:'1px solid rgba(23,40,51,.15)'}} />
