              })}
            </div>}

            <div style={{position:'absolute',left:focus.x,top:focus.y,width:focus.w,height:focus.h,zIndex:14,opacity:.52*progress(f,cryptoAt,cryptoEnd),pointerEvents:'none',color:focusColor}}>
