      </div>
    </div>
  </AbsoluteFill>;
};

import React from "react";
import { AbsoluteFill, Sequence, useCurrentFrame, useVideoConfig, interpolate, spring, Easing, random } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; id?: string | number; word?: string; text?: string; startFrame?: number; endFrame?: number };
type ShotProps = { wordCues?: WordCue[] };

const C = { ivory: '#F3F1E9', white: '#FFFFFF', graphite: '#172833', gray: '#9AA8AD', teal: '#167D8D', cobalt: '#365FDB', coral: '#EE735E' };
const LOCAL_CUES = [
  [317, 0, 'But,'], [318, 48, 'if'], [319, 58, 'you'], [320, 68, 'vote'], [321, 82, 'from'], [322, 94, 'home,'],
  [323, 134, "what's"], [324, 156, 'stopping'], [325, 183, 'someone'], [326, 206, 'from'], [327, 217, 'standing'],
  [328, 241, 'behind'], [329, 260, 'you'], [330, 268, 'and'], [331, 276, 'saying,'], [332, 343, 'Vote'],
  [333, 355, 'for'], [334, 362, 'this'], [335, 370, 'candidate?'], [336, 441, 'Or'], [337, 457, 'worse,'],
  [338, 523, 'show'], [339, 544, 'me'], [340, 552, 'your'], [341, 561, 'screen.']
] as const;
const EASE = Easing.bezier(0.4, 0, 0.2, 1);
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const cleanWord = (value: string) => value.toLowerCase().replace(/[^a-z]/g, '');

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cue = (wordIndex: number, fallback: number) => {
    const local = LOCAL_CUES.find((item) => item[0] === wordIndex);
    const explicit = cues.find((item) => item.wordIndex === wordIndex || item.index === wordIndex || String(item.id) === String(wordIndex) || item.id === `W${wordIndex}`);
    const positional = cues.length === LOCAL_CUES.length ? cues[wordIndex - 317] : undefined;
    const textual = local ? cues.find((item) => (item.word || item.text || '') === local[2]) : undefined;
    const normalized = local ? cues.find((item) => cleanWord(item.word || item.text || '') === cleanWord(local[2])) : undefined;
    const match = explicit || positional || textual || normalized;
    return match && typeof match.startFrame === 'number' ? match.startFrame : fallback;
  };
  const cueEnd = (wordIndex: number, fallback: number) => {
    const match = cues.find((item) => item.wordIndex === wordIndex || item.index === wordIndex || String(item.id) === String(wordIndex) || item.id === `W${wordIndex}`) || (cues.length === LOCAL_CUES.length ? cues[wordIndex - 317] : undefined);
    return match && typeof match.endFrame === 'number' ? match.endFrame : fallback;
  };
  const progress = (start: number, end: number) => interpolate(frame, [start, Math.max(start + 1, end)], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: EASE });
  const linear = (start: number, end: number) => interpolate(frame, [start, Math.max(start + 1, end)], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  const tIf = cue(318, 48);
  const tFrom = cue(321, 82);
  const tHomeEnd = cueEnd(322, 114);
  const tSomeone = cue(325, 183);
  const tStanding = cue(327, 217);
  const tBehind = cue(328, 241);
  const tYouEnd = cueEnd(329, 272);
  const tSaying = cue(331, 276);
  const tVote = cue(332, 343);
  const tFor = cue(333, 355);
  const tThis = cue(334, 362);
  const tCandidate = cue(335, 370);
  const tCandidateEnd = cueEnd(335, 396);
  const tOr = cue(336, 441);
  const tWorse = cue(337, 457);
  const tShow = cue(338, 523);
  const tMe = cue(339, 544);
  const tYour = cue(340, 552);
  const tScreen = cue(341, 561);
  const tScreenEnd = cueEnd(341, 589);

  const establish = progress(tIf, cueEnd(320, 83));
  const retreat = progress(tFrom, tHomeEnd);
  const follow = progress(tSomeone, tYouEnd);
  const choicePush = progress(tVote, tCandidateEnd);
  const pullback = progress(tOr, tScreenEnd);
  let camera = { zoom: lerp(1.74, 1.025, establish), focusX: lerp(865, 832, establish), focusY: lerp(332, 440, establish) };
  camera = { zoom: lerp(camera.zoom, 1.055, retreat), focusX: lerp(camera.focusX, 806, retreat), focusY: lerp(camera.focusY, 424, retreat) };
  camera = { zoom: lerp(camera.zoom, 1.075, follow), focusX: lerp(camera.focusX, 923, follow), focusY: lerp(camera.focusY, 440, follow) };
  camera = { zoom: lerp(camera.zoom, 1.24, choicePush), focusX: lerp(camera.focusX, 895, choicePush), focusY: lerp(camera.focusY, 436, choicePush) };
  camera = { zoom: lerp(camera.zoom, 1, pullback), focusX: lerp(camera.focusX, 840, pullback), focusY: lerp(camera.focusY, 445, pullback) };
  const cameraX = 840 - camera.focusX * camera.zoom;
  const cameraY = 445 - camera.focusY * camera.zoom;

  const arrival = frame < 2 ? 0 : frame >= 30 ? 1 : spring({ frame: frame - 2, fps, durationInFrames: 28, config: { stiffness: 160, damping: 14, mass: 0.8 } });
  const arrivalY = (1 - arrival) * 16;
  const laptopScale = 0.991 + 0.009 * arrival;
  const identityOpacity = linear(cue(320, 68), cue(320, 68) + 13);
  const identitySpring = spring({ frame: Math.max(0, frame - cue(320, 68)), fps, config: { stiffness: 160, damping: 14, mass: 0.85 } });
  const identityY = 584 + 22 * (1 - identitySpring);
  const personOpacity = linear(tSomeone, tSomeone + 16);
  const personTravel = progress(tSomeone, tYouEnd);
  const standing = progress(tStanding, tYouEnd);
  const personX = lerp(1536, 1237, personTravel);
  const personY = lerp(535, 469, standing);
  const personRotation = lerp(9, -4, progress(tBehind, tYouEnd));
  const barrierX = lerp(500, -930, retreat);
  const barrierOpacity = 1 - linear(tHomeEnd - 8, tHomeEnd + 4);
  const boundaryOpacity = 0.12 + 0.58 * retreat;
  const influence = progress(tSaying, tSaying + 36);
  const scrutiny = progress(tWorse, tShow);
  const focusOpacity = linear(tVote, tVote + 9) * (1 - 0.7 * pullback);
  const bracket = progress(tShow, tScreenEnd);
  const bracketOpacity = linear(tShow, tShow + 11);
  const bx = lerp(853, 481, bracket);
  const by = lerp(417, 185, bracket);
  const bw = lerp(307, 703, bracket);
  const bh = lerp(72, 427, bracket);
  const bl = lerp(18, 53, bracket);
  const bracketPath = `M ${bx + bl} ${by} H ${bx} V ${by + bl} M ${bx + bw - bl} ${by} H ${bx + bw} V ${by + bl} M ${bx} ${by + bh - bl} V ${by + bh} H ${bx + bl} M ${bx + bw - bl} ${by + bh} H ${bx + bw} V ${by + bh - bl}`;
  const scale = Math.min(width / 1920, height / 1080);
  const FocusFrame = mg.FocusFrame as React.ComponentType<any>;

  const titleWords = [
    { text: 'Vote', at: tVote },
    { text: 'for', at: tFor },
    { text: 'this', at: tThis },
    { text: 'candidate?', at: tCandidate }
  ];
  const kickerWords = [
    { text: 'show', at: tShow },
    { text: 'me', at: tMe },
    { text: 'your', at: tYour },
    { text: 'screen.', at: tScreen }
  ];
  const renderWord = (word: { text: string; at: number }, index: number) => {
    const enter = linear(word.at, word.at + 7);
    const settle = spring({ frame: Math.max(0, frame - word.at), fps, config: { stiffness: 160, damping: 14, mass: 0.7 } });
    return <span key={word.text + index} style={{ display: 'inline-block', whiteSpace: 'pre', opacity: enter, transform: `translateY(${(1 - settle) * 7}px)` }}>{word.text}{index < 3 ? ' ' : ''}</span>;
  };

  return (
    <AbsoluteFill style={{ backgroundColor: C.ivory, overflow: 'hidden', color: C.graphite, fontFamily: 'Inter, Arial, sans-serif' }}>
      <div style={{ position: 'absolute', width: 1920, height: 1080, left: (width - 1920 * scale) / 2, top: (height - 1080 * scale) / 2, transform: `scale(${scale})`, transformOrigin: '0 0' }}>
        <div style={{ position: 'absolute', left: 120, top: 158, width: 1680, height: 890, borderRadius: 24, overflow: 'hidden', background: 'linear-gradient(150deg, rgba(255,255,255,0.92) 0%, rgba(255,255,255,0.66) 58%, rgba(236,237,229,0.74) 100%)', boxShadow: '0 0 0 1px rgba(23,40,51,0.12), 0 16px 45px rgba(23,40,51,0.025)' }}>
          <div style={{ position: 'absolute', inset: 0, opacity: 0.28, backgroundImage: 'radial-gradient(circle, rgba(154,168,173,0.55) 0.85px, transparent 1.15px)', backgroundSize: '40px 40px' }} />
          <div style={{ position: 'absolute', width: 1680, height: 890, transform: `translate(${cameraX}px, ${cameraY}px) scale(${camera.zoom})`, transformOrigin: '0 0', willChange: 'transform' }}>
            <div style={{ position: 'absolute', left: 364, top: 624, width: 940, height: 114, borderRadius: '50%', background: 'radial-gradient(ellipse, rgba(23,40,51,0.115), rgba(23,40,51,0) 69%)', transform: 'rotate(-1deg)' }} />

            <svg width={1680} height={890} viewBox="0 0 1680 890" style={{ position: 'absolute', inset: 0, overflow: 'visible' }} aria-hidden="true">
              <path d="M 334 742 L 756 579 L 1492 579 M 756 579 L 540 819 M 756 579 L 756 804" fill="none" stroke={C.gray} strokeWidth={1} opacity={0.2} />
              <path d="M 743 620 L 1498 410 M 749 645 L 1497 434" fill="none" stroke={C.gray} strokeWidth={1} strokeDasharray="3 10" opacity={0.16 + 0.08 * follow} />
            </svg>

            <div style={{ position: 'absolute', left: 425, top: 155 + arrivalY, width: 825, height: 565, transform: `scale(${laptopScale})`, transformOrigin: '50% 80%' }}>
              {/* Laptop silhouette: exactly eleven SVG primitives. The fifth interface shape is the persistent record tile. */}
              <svg width={825} height={565} viewBox="0 0 825 565" aria-label="Laptop with an unchanged record and a blank choice row" style={{ display: 'block', overflow: 'visible', filter: 'drop-shadow(0px 10px 15px rgba(23,40,51,0.065))' }}>
                {/* 1. Lid */}
                <rect x={35} y={10} width={745} height={463} rx={24} fill="#E5E9E7" stroke={C.graphite} strokeOpacity={0.65} strokeWidth={2} />
                {/* 2. Display inset */}
                <rect x={64} y={40} width={686} height={410} rx={9} fill={C.white} stroke={C.graphite} strokeOpacity={0.21} strokeWidth={1.3} />
                {/* 3. Inert camera dot: no glow, pulse, or interaction. */}
                <circle cx={407.5} cy={25} r={3.1} fill={C.graphite} opacity={0.52} />
                {/* 4. Hinge */}
                <rect x={232} y={467} width={350} height={9} rx={4.5} fill="#BBC5C5" stroke={C.graphite} strokeOpacity={0.26} strokeWidth={1} />
                {/* 5. Base */}
                <path d="M 36 476 L 779 476 L 823 535 Q 825 539 818 542 L 781 553 L 42 553 L 6 542 Q -1 539 3 535 Z" fill="#E8ECEA" stroke={C.graphite} strokeOpacity={0.6} strokeWidth={1.6} strokeLinejoin="round" />
                {/* 6. Trackpad */}
                <path d="M 345 492 L 469 492 L 483 530 L 331 530 Z" fill="#F5F7F5" stroke={C.gray} strokeOpacity={0.7} strokeWidth={1.2} strokeLinejoin="round" />
                {/* 7. Interface: quiet masthead bar */}
                <rect x={91} y={69} width={244} height={13} rx={3} fill="#CBD4D4" />
                {/* 8. Interface: single header divider */}
                <path d="M 90 104 H 723" fill="none" stroke="#E0E6E5" strokeWidth={1.4} />
                {/* 9. Interface: blank illustrative choice row, deliberately unselected. */}
                <rect x={438} y={270} width={287} height={56} rx={6} fill="#FCFDFB" stroke={C.gray} strokeWidth={1.5} />
                {/* 10. Interface: neutral footer rule */}
                <path d="M 91 396 H 246" fill="none" stroke="#DDE4E2" strokeWidth={6} strokeLinecap="round" />
