              <div style={{ position: 'absolute', left: 244, top: 132, width: 174, height: 177, color: '#FFFFFF', pointerEvents: 'none' }}>
                {[{ left: 13, top: 13, side: 'tl' }, { right: 13, top: 13, side: 'tr' }, { left: 13, bottom: 13, side: 'bl' }, { right: 13, bottom: 13, side: 'br' }].map((mark) => (
                  <div key={mark.side} style={{ position: 'absolute', left: 'left' in mark ? mark.left : undefined, right: 'right' in mark ? mark.right : undefined, top: 'top' in mark ? mark.top : undefined, bottom: 'bottom' in mark ? mark.bottom : undefined, width: 11, height: 11, borderLeft: mark.side.endsWith('l') ? '1.5px solid rgba(255,255,255,0.8)' : undefined, borderRight: mark.side.endsWith('r') ? '1.5px solid rgba(255,255,255,0.8)' : undefined, borderTop: mark.side.startsWith('t') ? '1.5px solid rgba(255,255,255,0.8)' : undefined, borderBottom: mark.side.startsWith('b') ? '1.5px solid rgba(255,255,255,0.8)' : undefined }} />
                ))}
                <div style={{ position: 'absolute', left: 36, top: 47, width: 99, height: 76, border: '1px solid rgba(255,255,255,0.4)', borderRadius: 3 }}>
                  <div style={{ position: 'absolute', left: 13, top: 16, width: 67, height: 3, background: 'rgba(255,255,255,0.7)' }} />
                  <div style={{ position: 'absolute', left: 13, top: 31, width: 51, height: 3, background: 'rgba(255,255,255,0.52)' }} />
                  <div style={{ position: 'absolute', left: 13, top: 47, width: 59, height: 3, background: 'rgba(255,255,255,0.52)' }} />
                </div>
              </div>
            </div>

            {/* Coral is scrutiny and an unresolved physical boundary, not a fraud verdict. */}
            <svg width={1680} height={890} viewBox="0 0 1680 890" style={{ position: 'absolute', inset: 0, pointerEvents: 'none' }} aria-hidden="true">
