              <path d="M 616 752 L 632 774 M 1462 460 L 1478 482" fill="none" stroke={C.coral} strokeWidth={1.5} opacity={boundaryOpacity} />
              <path d="M 1270 535 C 1209 535 1197 453 1168 453" fill="none" stroke={C.coral} strokeWidth={2} pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - influence} opacity={0.75 * influence} />
              <path d="M 1168 444 V 462" fill="none" stroke={C.coral} strokeWidth={1.5} opacity={influence} />
              <path d="M 1328 519 L 1185 205 M 1328 560 L 1185 601" fill="none" stroke={C.coral} strokeWidth={1.25} opacity={0.27 * scrutiny * bracket} />
            </svg>

            {/* The nearby person is represented only by a separate, neutral abstract tile. */}
            <div style={{ position: 'absolute', left: personX, top: personY, width: 152, height: 167, borderRadius: 10, background: 'linear-gradient(145deg, #FFFFFF, #E5E9E5)', border: '1.5px solid rgba(23,40,51,0.43)', boxShadow: '8px 14px 0 rgba(23,40,51,0.035), 0 17px 26px rgba(23,40,51,0.065)', opacity: personOpacity, transform: `rotate(${personRotation}deg) skewY(-3deg)`, transformOrigin: '50% 85%' }}>
              <div style={{ position: 'absolute', inset: 15, border: '1px solid rgba(154,168,173,0.5)', borderRadius: 3 }} />
              <div style={{ position: 'absolute', left: 37, top: 48, width: 77, height: 67, border: '1px solid rgba(154,168,173,0.63)', borderRadius: 3, background: 'rgba(154,168,173,0.06)' }} />
            </div>

            {/* Identity evidence sits at the near viewing edge. It never flows into the record or activates the camera. */}
            <div style={{ position: 'absolute', left: 1080, top: identityY, width: 137, height: 156, borderRadius: 10, background: C.cobalt, border: '1px solid rgba(31,66,170,0.45)', boxShadow: '6px 10px 0 rgba(54,95,219,0.08), 0 17px 23px rgba(23,40,51,0.1)', opacity: identityOpacity, transform: 'rotate(-8deg) skewY(-3deg)', transformOrigin: '50% 90%' }}>
              <div style={{ position: 'absolute', left: 17, top: 17, width: 17, height: 17, borderTop: '1.5px solid rgba(255,255,255,0.7)', borderLeft: '1.5px solid rgba(255,255,255,0.7)' }} />
              <div style={{ position: 'absolute', right: 17, bottom: 17, width: 17, height: 17, borderBottom: '1.5px solid rgba(255,255,255,0.7)', borderRight: '1.5px solid rgba(255,255,255,0.7)' }} />
