          <div style={{ position: "absolute", left: 866, top: 43, width: 791, height: 811, border: "1px solid rgba(23,40,51,0.18)", borderRadius: 12, opacity: 0.48 * handoff, pointerEvents: "none" }} />
        </div>
      </div>
    </AbsoluteFill>
  );
};

import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; id?: string | number; startFrame?: number; start?: number; word?: string; text?: string };
type ShotProps = { wordCues?: WordCue[] };
type Box = { left: number; top: number; width: number; height: number };

const C = { ivory: "#F3F1E9", porcelain: "#FFFFFF", graphite: "#172833", gray: "#9AA8AD", teal: "#167D8D", cobalt: "#365FDB", coral: "#EE735E" };
const sans = '"Inter", "Arial", sans-serif';
const tight = '"Inter Tight", "Inter", "Arial", sans-serif';
const mono = '"IBM Plex Mono", "SFMono-Regular", monospace';
const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
const soft = { ...clamp, easing: Easing.bezier(0.4, 0, 0.2, 1) };
const saturate = (n: number) => Math.min(1, Math.max(0, n));

const SelectionTile: React.FC<{ left: number; top: number; width: number; height: number; selected: number; recorded: boolean; order: number }> = ({ left, top, width, height, selected, recorded, order }) => {
  const accent = recorded ? C.teal : C.graphite;
  const inset = width > 220 ? 23 : 16;
  const startY = width > 220 ? 100 : 67;
  const step = width > 220 ? 47 : 40;
  return (
    <div style={{ position: "absolute", left, top, width, height, boxSizing: "border-box", overflow: "hidden", borderRadius: 12, background: recorded ? "#E4F0EF" : "#FAFBFA", border: `1.5px solid ${recorded ? "rgba(22,125,141,0.52)" : "rgba(23,40,51,0.3)"}`, boxShadow: "0 6px 14px rgba(23,40,51,0.035)" }}>
      <div style={{ position: "absolute", left: inset, top: 22, width: recorded ? 38 : 28, height: 5, borderRadius: 3, background: accent, opacity: recorded ? 0.8 : 0.4 }} />
      <div style={{ position: "absolute", right: inset, top: 19, display: "flex", gap: 5 }}>
        {[0, 1, 2].map((i) => <div key={i} style={{ width: 4, height: 10, borderRadius: 1, background: accent, opacity: i === order % 3 ? 0.6 : 0.17 }} />)}
      </div>
      {[0, 1, 2].map((row) => (
        <div key={row} style={{ position: "absolute", left: inset, right: inset, top: startY + row * step, height: 29, display: "flex", alignItems: "center", gap: 13 }}>
          <div style={{ width: 22, height: 22, flexShrink: 0, borderRadius: 5, boxSizing: "border-box", border: `1.5px solid ${row === selected ? accent : recorded ? "rgba(22,125,141,0.36)" : "rgba(23,40,51,0.27)"}`, background: row === selected ? accent : "rgba(255,255,255,0.6)", display: "flex", alignItems: "center", justifyContent: "center" }}>
            {row === selected && <div style={{ width: 9, height: 5, borderLeft: "2px solid #FFFFFF", borderBottom: "2px solid #FFFFFF", transform: "translateY(-1px) rotate(-45deg)" }} />}
          </div>
          <div style={{ height: 4, width: row === 0 ? "66%" : row === 1 ? "53%" : "61%", borderRadius: 3, background: accent, opacity: row === selected ? 0.55 : 0.18 }} />
        </div>
      ))}
      <div style={{ position: "absolute", left: inset, right: inset, bottom: 22, height: 1, background: recorded ? "rgba(22,125,141,0.19)" : "rgba(23,40,51,0.13)" }} />
      <div style={{ position: "absolute", left: inset, bottom: 11, width: 25, height: 2, background: accent, opacity: 0.22 }} />
    </div>
  );
};

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const f = Math.max(0, Math.min(frame, durationInFrames - 1));
  const fit = Math.min(width / 1920, height / 1080);

  const cue = (index: number, fallback: number) => {
    const found = cues.find((c) => c.wordIndex === index || c.index === index || c.id === index || c.id === `W${index}`);
    const entry = found || (cues.length === 38 ? cues[index - 437] : undefined);
    const value = entry?.startFrame ?? entry?.start;
    return typeof value === "number" && Number.isFinite(value) ? value : fallback;
  };
  const t = {
    blockchain: cue(441, 106), protect: cue(443, 144), integrity: cue(445, 173), information: cue(447, 217),
    after: cue(448, 273), recorded: cue(450, 303), it: cue(451, 374), cannot: cue(452, 380),
    guarantee: cue(453, 399), incoming: cue(456, 443), entering: cue(457, 483), system: cue(459, 518),
    correct: cue(461, 549), and: cue(462, 607), finally: cue(463, 631), question: cue(466, 706),
    what: cue(467, 782), problem: cue(468, 795), actually: cue(471, 837), trying: cue(472, 858), solve: cue(474, 883)
  };
  const progress = (start: number, end: number) => interpolate(f, [start, Math.max(start + 1, end)], [0, 1], soft);
  const reveal = (start: number, span = 16) => progress(start, start + span);
  const arrival = saturate(spring({ frame: f - 2, fps, durationInFrames: 28, config: { stiffness: 160, damping: 26, mass: 1 } }));
  const interpolateTrack = (times: number[], values: number[]) => {
    const ordered = times.reduce<number[]>((out, v, i) => { out.push(i === 0 ? v : Math.max(v, out[i - 1] + 1)); return out; }, []);
    return interpolate(f, ordered, values, soft);
  };

  const cameraTimes = [0, 30, 64, t.blockchain, t.protect + 23, t.integrity, t.information + 38, t.after, t.recorded + 25, t.it, t.cannot + 21, t.incoming, t.entering, t.system + 25, t.and, t.finally + 34, t.what, t.problem + 28];
  const zoom = interpolateTrack(cameraTimes, [1.58, 1.58, 1, 1, 1.045, 1.045, 1.05, 1.05, 1.025, 1.025, 1.015, 1.012, 1.01, 1.01, 1.01, 1, 1, 1]);
  const panX = interpolateTrack(cameraTimes, [0, 0, 0, 0, 32, 32, 35, 35, 27, 27, 10, -13, -29, -36, -36, 0, 0, 0]);
  const panY = interpolateTrack(cameraTimes, [48, 48, 0, 0, 10, 10, 7, 7, -3, -3, 0, 1, 3, 4, 4, 0, 0, 0]);
  const sharedRetreat = progress(t.and, t.finally + 34);
  const finalPull = progress(t.what, t.problem + 28);
  const planeScale = 1 - 0.035 * sharedRetreat - 0.035 * finalPull;
  const planeY = -6 * sharedRetreat - 10 * finalPull;
  const appearance = 0.76 + arrival * 0.24;
  const introShift = (1 - arrival) * 15;
  const integrityReveal = reveal(t.integrity, 22);
  const afterReveal = reveal(t.after, 22);
  const cannotReveal = reveal(t.cannot, 18);
  const incomingReveal = reveal(t.incoming, 22);
  const matchReveal = reveal(t.protect, 20);
  const scrutiny = reveal(t.entering, 22);
  const questionReveal = reveal(t.question, 22);

  let focus: Box = { left: 786, top: 307, width: 88, height: 342 };
  const shiftFocus = (target: Box, amount: number) => {
    focus = { left: focus.left + (target.left - focus.left) * amount, top: focus.top + (target.top - focus.top) * amount, width: focus.width + (target.width - focus.width) * amount, height: focus.height + (target.height - focus.height) * amount };
  };
  shiftFocus({ left: 764, top: 263, width: 132, height: 422 }, progress(30, 64));
  shiftFocus({ left: 87, top: 274, width: 626, height: 334 }, progress(t.blockchain, t.protect + 23));
  shiftFocus({ left: 80, top: 175, width: 640, height: 502 }, progress(t.integrity, t.recorded + 25));
  shiftFocus({ left: 952, top: 176, width: 616, height: 507 }, progress(t.it, t.system + 25));
  shiftFocus({ left: 17, top: 113, width: 1626, height: 615 }, progress(t.what, t.problem + 28));
  const FocusFrame = mg.FocusFrame as React.ComponentType<any>;
