export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const f = Math.min(frame, durationInFrames - 1);

  const normalize = (value: string) => value.toLowerCase().replace(/[^a-z0-9]/g, "");
  const cueFrame = (id: number, fallback: number, word: string) => {
    const byId = cues.find((cue) => {
      const raw = cue.wordIndex ?? cue.index ?? cue.id;
      return raw !== undefined && Number(String(raw).replace(/^W/i, "")) === id;
    });
    const byText = cues
      .filter((cue) => normalize(cue.word || cue.text || "") === normalize(word))
      .sort((a, b) => Math.abs(a.startFrame - fallback) - Math.abs(b.startFrame - fallback))[0];
    const match = byId || byText;
    return match && Number.isFinite(match.startFrame) ? match.startFrame : fallback;
  };
  const at = {
    transparency: cueFrame(479, 37, "transparency"),
    traditional: cueFrame(480, 113, "traditional"),
    already: cueFrame(484, 205, "already"),
    paper: cueFrame(488, 274, "paper"),
    ballots: cueFrame(489, 293, "ballots"),
    observers: cueFrame(490, 342, "observers"),
    audits: cueFrame(491, 408, "audits"),
    recounts: cueFrame(492, 459, "recounts"),
    publicly: cueFrame(494, 532, "publicly"),
    verifiable: cueFrame(495, 562, "verifiable"),
    procedures: cueFrame(496, 596, "procedures"),
    blockchain: cueFrame(497, 678, "blockchain"),
    isnt: cueFrame(498, 711, "isn't"),
    automatically: cueFrame(499, 731, "automatically"),
    more: cueFrame(500, 776, "more"),
    secure: cueFrame(501, 786, "secure"),
    just: cueFrame(502, 832, "just"),
    because: cueFrame(503, 848, "because"),
    its: cueFrame(504, 873, "it's"),
    lastBlockchain: cueFrame(505, 886, "blockchain"),
  };

  const linear = (start: number, length: number) => interpolate(f, [start, start + length], [0, 1], clamp);
  const soft = (start: number, length: number) => interpolate(f, [start, start + length], [0, 1], {
    ...clamp,
    easing: Easing.inOut(Easing.cubic),
  });
  const arrive = (start: number, length = 28) => {
    if (f < start) return 0;
    if (f >= start + length) return 1;
    return spring({
      frame: f - start,
      fps,
      durationInFrames: length,
      config: { stiffness: 160, damping: 2 * Math.sqrt(160), mass: 1, overshootClamping: true },
    });
  };

  const arrival = arrive(2, 28);
  const previousOpacity = 1 - linear(2, 24);
  const tableOpacity = linear(2, 12);
  const stageOffsetY = 26 * (1 - arrival);
  const planeOpacity = soft(at.traditional, 28);
  const planeSettle = arrive(at.traditional, 28);
  const folioEntrance = arrive(at.paper, 30);
  const folioOpacity = linear(at.paper, 14);
  const titleEntrance = arrive(2, 28);

  type Pose = { zoom: number; x: number; y: number };
  let camera: Pose = { zoom: 1.68, x: 488, y: 574 };
  const move = (start: number, end: number, target: Pose) => {
    const p = interpolate(f, [start, end], [0, 1], { ...clamp, easing: Easing.inOut(Easing.cubic) });
    camera = {
      zoom: camera.zoom + (target.zoom - camera.zoom) * p,
      x: camera.x + (target.x - camera.x) * p,
      y: camera.y + (target.y - camera.y) * p,
    };
  };
  move(2, Math.max(30, at.transparency + 53), { zoom: 1, x: 840, y: 445 });
  move(at.paper, at.ballots + 29, { zoom: 1.38, x: 565, y: 432 });
  move(at.observers, at.observers + 41, { zoom: 1.23, x: 878, y: 421 });
  move(at.audits, at.audits + 25, { zoom: 1.17, x: 958, y: 422 });
  move(at.recounts, at.recounts + 40, { zoom: 1.12, x: 997, y: 444 });
  move(at.publicly, at.procedures + 38, { zoom: 1, x: 840, y: 445 });
  move(at.blockchain, at.blockchain + 31, { zoom: 1, x: 854, y: 445 });
  const panX = 840 - camera.x * camera.zoom;
  const panY = 445 - camera.y * camera.zoom;

  const tabs = [
    { key: "observers", label: "observers", y: 141, h: 108, start: at.observers },
    { key: "audits", label: "audits", y: 286, h: 108, start: at.audits },
    { key: "recounts", label: "recounts", y: 431, h: 108, start: at.recounts },
    { key: "procedures", label: "publicly verifiable procedures", y: 576, h: 130, start: at.publicly },
  ];

  const lastTab = tabs[3];
  const finalConnectorY = lastTab.y + lastTab.h / 2;
  const trace = soft(at.publicly, at.procedures + 38 - at.publicly);
  const finalPulseX = interpolate(trace, [0, 0.42, 1], [TAB_X, INSPECTION_X, 600], clamp);
  const finalPulseY = interpolate(trace, [0, 0.42, 0.72, 1], [finalConnectorY, finalConnectorY, 486, 486], clamp);
  const finalPulseOpacity = interpolate(f, [at.publicly, at.publicly + 10, at.procedures + 26, at.procedures + 38], [0, 0.72, 0.72, 0], clamp);
  const priorPulseOpacity = interpolate(f, [at.already, at.already + 8, at.already + 33, at.already + 46], [0, 0.55, 0.55, 0], clamp);

  const blockchainEntrance = arrive(at.blockchain, 26);
  const blockchainOpacity = linear(at.blockchain, 16);
  const boundaryExtent = soft(at.isnt, 16);
  const boundarySupport = soft(at.secure, 20);
  const boundaryDraw = Math.min(1, boundaryExtent * 0.76 + boundarySupport * 0.24);
  const secondScrutiny = interpolate(f, [at.just, at.because, at.its, at.lastBlockchain + 20], [0, 0.15, 0.15, 0], clamp);
  const boundaryOpacity = linear(at.isnt, 12) * (0.69 + 0.21 * boundarySupport + secondScrutiny * 0.5);
  const kickerSwap = linear(at.isnt, 10);
  const kickerPhrases = [
    { text: "isn't", start: at.isnt },
    { text: "automatically", start: at.automatically },
    { text: "more", start: at.more },
    { text: "secure", start: at.secure },
  ];

  const fit = Math.min(width / 1920, height / 1080);
  const rootLeft = (width - 1920 * fit) / 2;
  const rootTop = (height - 1080 * fit) / 2;
  const techStyle: React.CSSProperties = { fontFamily: mono, fontWeight: 500, fontSize: 15, letterSpacing: "0.045em" };

  return (
    <AbsoluteFill style={{ backgroundColor: C.ivory, overflow: "hidden", color: C.graphite, fontFamily: sans }}>
      <div style={{ position: "absolute", left: rootLeft, top: rootTop, width: 1920, height: 1080, transform: `scale(${fit})`, transformOrigin: "0 0" }}>
        <AbsoluteFill style={{ pointerEvents: "none", backgroundImage: "radial-gradient(ellipse at 35% 30%, rgba(255,255,255,0.75) 0%, rgba(255,255,255,0) 65%)" }} />

        {/* This viewport contains one camera transform. The title never moves with it. */}
        <div style={{ position: "absolute", left: 94, top: 163, width: 1744, height: 911, overflow: "hidden", borderRadius: 14 }}>
          <div style={{ position: "absolute", left: 26, top: 7, width: 1680, height: 890 }}>
            <div style={{ position: "absolute", inset: 0, transformOrigin: "0 0", transform: `translate3d(${panX}px, ${panY + stageOffsetY}px, 0) scale(${camera.zoom})` }}>
              {/* The old comparison surfaces dissolve; the record itself remains. */}
              {previousOpacity > 0 && (
                <div style={{ position: "absolute", inset: 0, opacity: previousOpacity, pointerEvents: "none" }}>
                  {[{ x: 78, w: 552 }, { x: 700, w: 552 }].map((old, i) => (
                    <div key={i} style={{ position: "absolute", left: old.x, top: 484, width: old.w, height: 374, background: "rgba(255,255,255,0.87)", border: "1px solid rgba(23,40,51,0.18)", borderRadius: 15, boxShadow: "0 10px 28px rgba(23,40,51,0.045)" }}>
                      <div style={{ position: "absolute", left: 30, right: 30, top: 69, height: 1, background: "rgba(23,40,51,0.12)" }} />
                      <div style={{ position: "absolute", left: 30, top: 30, width: i ? 149 : 180, height: 5, borderRadius: 2, background: "rgba(154,168,173,0.28)" }} />
                    </div>
                  ))}
                </div>
              )}

              {/* 1680 × 890 archival table, with a quiet, non-directional layout. */}
              <div style={{ position: "absolute", inset: 0, opacity: tableOpacity, borderRadius: 12, background: "linear-gradient(112deg, #FFFEFB 0%, #FAF9F4 62%, #F7F6F0 100%)", border: "1px solid rgba(23,40,51,0.17)", boxShadow: "0 8px 25px rgba(23,40,51,0.055)", boxSizing: "border-box" }}>
                <div style={{ position: "absolute", left: 30, right: 30, top: 28, bottom: 28, border: "1px solid rgba(23,40,51,0.045)", borderRadius: 3 }} />
                <div style={{ position: "absolute", left: 42, right: 42, top: 77, height: 1, background: "rgba(23,40,51,0.12)" }} />
                <div style={{ position: "absolute", left: 42, top: 30, ...techStyle, fontSize: 13, color: "#819094", opacity: soft(at.traditional, 20) }}>ELECTION SYSTEMS / ARCHIVE</div>
                <div style={{ position: "absolute", left: 1551, top: 94, bottom: 151, width: 1, background: "rgba(23,40,51,0.10)" }} />
                {[132, 278, 424, 570, 716].map((y) => (
                  <div key={y} style={{ position: "absolute", left: 30, top: y, width: 8, height: 1, background: "rgba(23,40,51,0.19)" }} />
                ))}
              </div>

              <div style={{ position: "absolute", left: PLANE_X, top: PLANE_Y, width: PLANE_W, height: PLANE_H, opacity: planeOpacity, transform: `translateY(${8 * (1 - planeSettle)}px)`, background: "linear-gradient(125deg, rgba(255,255,255,0.56), rgba(255,255,255,0.27))", border: "1px solid rgba(154,168,173,0.30)", borderRadius: 5, boxSizing: "border-box" }}>
                <div style={{ position: "absolute", left: 20, top: 11, ...techStyle, fontSize: 12, letterSpacing: "0.11em", color: "#7E8A8F" }}>SHARED INSPECTION PLANE</div>
                <div style={{ position: "absolute", left: 12, right: 12, top: 34, height: 1, background: "rgba(154,168,173,0.15)" }} />
                <div style={{ position: "absolute", left: INSPECTION_X - PLANE_X, top: 64, bottom: 45, width: 1, background: "rgba(111,126,132,0.32)" }} />
              </div>

              {/* Shared-plane connections are parallel, open, and never arrowed. */}
              <svg width={1680} height={890} viewBox="0 0 1680 890" style={{ position: "absolute", inset: 0, overflow: "visible", pointerEvents: "none" }}>
                <path d="M600 486 H758" stroke="#7F8D93" strokeWidth={1.4} fill="none" pathLength={1} strokeDasharray="1" strokeDashoffset={1 - soft(at.paper + 12, 35)} opacity={folioOpacity * 0.72} />
                {tabs.map((tab) => {
                  const draw = soft(tab.start + 4, tab.key === "procedures" ? 36 : 24);
                  const centerY = tab.y + tab.h / 2;
                  const pulse = soft(tab.start + 10, 32);
                  const pulseAlpha = tab.key === "procedures" ? 0 : interpolate(f, [tab.start + 9, tab.start + 17, tab.start + 32, tab.start + 44], [0, 0.55, 0.55, 0], clamp);
                  const pulseX = TAB_X + (INSPECTION_X - TAB_X) * pulse;
