import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = {
  wordIndex?: number;
  index?: number;
  globalIndex?: number;
  startFrame?: number;
  start?: number;
  word?: string;
  text?: string;
};
type ShotProps = { wordCues?: WordCue[] };
type CameraKey = { frame: number; zoom: number; cx: number; cy: number };

const C = {
  ivory: "#F3F1E9",
  paper: "#FFFFFF",
  graphite: "#172833",
  gray: "#9AA8AD",
  teal: "#167D8D",
  cobalt: "#365FDB",
  coral: "#EE735E",
};
const FONT = '"Inter", "Arial", sans-serif';
const HEAD = '"Inter Tight", "Inter", "Arial", sans-serif';
const MONO = '"IBM Plex Mono", "Courier New", monospace';
const CLAMP = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
const EASE = Easing.bezier(0.42, 0, 0.22, 1);
const ANCHORS = [0, 9, 69, 86, 98, 159, 176, 242, 246, 266, 275, 303, 331, 367, 392, 461, 479, 529, 568, 576, 627, 702];
const WORDS = ["for", "elections", "we", "need", "something", "much", "harder", "a", "system", "that", "provides", "accurate", "counting", "voter", "authentication", "ballot", "secrecy", "resistance", "to", "coercion", "accessibility", "auditability"];
const clean = (value: string) => value.toLowerCase().replace(/[^a-z]/g, "");
const ease = (frame: number, from: number, to: number, a: number, b: number) => interpolate(frame, [from, Math.max(from + 1, to)], [a, b], { ...CLAMP, easing: EASE });

const RecordTile: React.FC = () => (
  <div style={{ width: 156, height: 110, borderRadius: 16, background: C.teal, border: "1px solid rgba(255,255,255,0.48)", boxShadow: "0 8px 20px rgba(22,125,141,0.16)", position: "relative" }}>
    <div style={{ position: "absolute", left: 19, top: 19, width: 26, height: 32, border: "2px solid rgba(255,255,255,0.92)", borderRadius: 4 }}>
      <div style={{ position: "absolute", left: 5, top: 8, width: 12, height: 2, background: "rgba(255,255,255,0.9)" }} />
      <div style={{ position: "absolute", left: 5, top: 16, width: 9, height: 2, background: "rgba(255,255,255,0.72)" }} />
    </div>
    <div style={{ position: "absolute", left: 61, top: 25, width: 71, height: 3, borderRadius: 2, background: "rgba(255,255,255,0.94)" }} />
    <div style={{ position: "absolute", left: 61, top: 39, width: 50, height: 3, borderRadius: 2, background: "rgba(255,255,255,0.57)" }} />
    <div style={{ position: "absolute", left: 19, right: 19, top: 67, height: 1, background: "rgba(255,255,255,0.3)" }} />
    <div style={{ position: "absolute", left: 19, top: 80, fontFamily: MONO, fontSize: 12, fontWeight: 500, color: C.paper, letterSpacing: 1.4 }}>VOTE RECORD</div>
  </div>
);

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cueFrame = (id: number, fallback: number) => {
    const offset = id - 506;
    const exact = cues.find((cue) => cue.wordIndex === id || cue.index === id || cue.globalIndex === id);
    const matched = exact || cues.find((cue) => clean(cue.word || cue.text || "") === WORDS[offset]);
    const cue = matched || (cues.length === 22 ? cues[offset] : undefined);
    const value = cue?.startFrame;
    return typeof value === "number" && Number.isFinite(value) ? value : fallback;
  };
  const times = ANCHORS.map((fallback, i) => cueFrame(506 + i, fallback));
  const shift = (base: number, index: number) => base + times[index] - ANCHORS[index];
  const f = Math.min(frame, durationInFrames - 1);
  const settle = spring({ frame: Math.max(0, f - 2), fps, config: { stiffness: 160, damping: 26, mass: 1 } });
  const cameraKeys: CameraKey[] = [
    { frame: 0, zoom: 1.7, cx: 481, cy: 799 },
    { frame: times[2], zoom: 1.7, cx: 481, cy: 799 },
    { frame: times[2] + 30, zoom: 1, cx: 960, cy: 540 },
    { frame: times[7], zoom: 1, cx: 960, cy: 540 },
    { frame: shift(298, 10), zoom: 1.3, cx: 625, cy: 483 },
    { frame: shift(349, 12), zoom: 1.3, cx: 625, cy: 483 },
    { frame: times[13], zoom: 1.3, cx: 960, cy: 483 },
    { frame: shift(439, 14), zoom: 1.3, cx: 960, cy: 483 },
    { frame: times[15], zoom: 1.3, cx: 1295, cy: 483 },
    { frame: shift(518, 16), zoom: 1.3, cx: 1295, cy: 483 },
    { frame: shift(547, 17), zoom: 1.3, cx: 625, cy: 629 },
    { frame: shift(605, 19), zoom: 1.3, cx: 625, cy: 629 },
    { frame: times[20], zoom: 1.3, cx: 960, cy: 629 },
    { frame: shift(680, 20), zoom: 1.3, cx: 960, cy: 629 },
    { frame: times[21], zoom: 1.3, cx: 1295, cy: 629 },
    { frame: shift(720, 21), zoom: 1.3, cx: 1295, cy: 629 },
    { frame: shift(750, 21), zoom: 1, cx: 960, cy: 540 },
  ];
  let camera = cameraKeys[cameraKeys.length - 1];
  for (let i = 0; i < cameraKeys.length - 1; i++) {
    const a = cameraKeys[i];
    const b = cameraKeys[i + 1];
    if (f <= b.frame) {
      camera = {
        frame: f,
        zoom: ease(f, a.frame, b.frame, a.zoom, b.zoom),
        cx: ease(f, a.frame, b.frame, a.cx, b.cx),
        cy: ease(f, a.frame, b.frame, a.cy, b.cy),
      };
      break;
    }
  }
  const settlingAmount = f < times[2] ? 1 - settle : 0;
  const panX = 960 - (camera.cx + settlingAmount * 7) * camera.zoom;
  const panY = 540 - (camera.cy + settlingAmount * 9) * camera.zoom;
  const infrastructure = ease(f, times[2], times[2] + 28, 0, 1);
  const systemOpacity = ease(f, times[8], times[8] + 14, 0.52, 1);
  const headlineOpacity = ease(f, 2, 13, 0, 1);
  const kickerOpacity = ease(f, times[4], times[4] + 17, 0, 1);
  const returnStart = shift(720, 21);
  const returnEnd = shift(750, 21);
  const nodes = [
    { x: 265, y: 357, start: times[11], parts: [{ text: "accurate", at: times[11] }, { text: "counting", at: times[12] }] },
    { x: 745, y: 357, start: times[13], parts: [{ text: "voter", at: times[13] }, { text: "authentication", at: times[14] }] },
    { x: 1225, y: 357, start: times[15], parts: [{ text: "ballot", at: times[15] }, { text: "secrecy", at: times[16] }] },
    { x: 265, y: 557, start: times[17], parts: [{ text: "resistance", at: times[17] }, { text: "to", at: times[18] }, { text: "coercion", at: times[19] }] },
    { x: 745, y: 557, start: times[20], parts: [{ text: "accessibility", at: times[20] }] },
    { x: 1225, y: 557, start: times[21], parts: [{ text: "auditability", at: times[21] }] },
  ];
  let focusIndex = -1;
  nodes.forEach((node, i) => { if (f >= node.start) focusIndex = i; });
  let focusX = nodes[0].x - 9;
  let focusY = nodes[0].y - 9;
  let focusWidth = 448;
  let focusHeight = 138;
  let focusOpacity = 0;
  if (focusIndex >= 0) {
    const node = nodes[focusIndex];
    const previous = nodes[Math.max(0, focusIndex - 1)];
    const travel = ease(f, node.start, node.start + 14, 0, 1);
    focusX = previous.x + (node.x - previous.x) * travel - 9;
    focusY = previous.y + (node.y - previous.y) * travel - 9;
    focusOpacity = ease(f, nodes[0].start, nodes[0].start + 9, 0, 0.86);
    if (focusIndex === 5) {
      const returning = ease(f, returnStart, returnEnd, 0, 1);
      focusX += (1650 - focusX) * returning;
      focusY += (429 - focusY) * returning;
      focusWidth += (94 - focusWidth) * returning;
      focusHeight += (180 - focusHeight) * returning;
      focusOpacity *= 1 - returning * 0.2;
    }
  }
  const fit = Math.min(width / 1920, height / 1080);

  return (
    <AbsoluteFill style={{ backgroundColor: C.ivory, color: C.graphite, fontFamily: FONT, overflow: "hidden" }}>
      <div style={{ position: "absolute", width: 1920, height: 1080, left: (width - 1920 * fit) / 2, top: (height - 1080 * fit) / 2, transform: `scale(${fit})`, transformOrigin: "0 0" }}>
        <div style={{ position: "absolute", inset: 0, backgroundImage: "radial-gradient(circle, rgba(23,40,51,0.12) 0.8px, transparent 1px)", backgroundSize: "32px 32px", opacity: 0.36 }} />
        <div style={{ position: "absolute", inset: 0, transform: `translate(${panX}px, ${panY}px) scale(${camera.zoom})`, transformOrigin: "0 0" }}>
          <div style={{ position: "absolute", left: 110, top: 166, width: 1700, height: 890, borderRadius: 28, background: "rgba(255,255,255,0.70)", border: "1px solid rgba(23,40,51,0.11)", boxShadow: "0 14px 54px rgba(23,40,51,0.045)", overflow: "hidden" }}>
            <div style={{ position: "absolute", inset: 0, backgroundImage: "linear-gradient(rgba(23,40,51,0.021) 1px, transparent 1px), linear-gradient(90deg, rgba(23,40,51,0.021) 1px, transparent 1px)", backgroundSize: "80px 80px" }} />
            <div style={{ position: "absolute", left: 0, right: 0, top: 702, height: 188, background: "rgba(243,241,233,0.30)", borderTop: "1px solid rgba(23,40,51,0.05)" }} />
          </div>

          <div style={{ position: "absolute", left: 184, top: 270, width: 1528, height: 468, opacity: infrastructure * systemOpacity }}>
            <div style={{ position: "absolute", inset: 0, borderLeft: "1.5px solid rgba(23,40,51,0.29)", borderTop: "1.5px solid rgba(23,40,51,0.29)", borderBottom: "1.5px solid rgba(23,40,51,0.29)", borderRadius: "16px 0 0 16px" }} />
            <div style={{ position: "absolute", right: 0, top: 0, width: 1.5, height: 137, background: "rgba(23,40,51,0.29)" }} />
            <div style={{ position: "absolute", right: 0, bottom: 0, width: 1.5, height: 113, background: "rgba(23,40,51,0.29)" }} />
            <div style={{ position: "absolute", right: -4, top: 135, width: 10, height: 2, background: C.coral }} />
            <div style={{ position: "absolute", right: -4, bottom: 111, width: 10, height: 2, background: C.coral }} />
          </div>

          <div style={{ position: "absolute", left: 229, top: 822, width: 1450, height: 1, background: "rgba(22,125,141,0.39)" }} />
          <div style={{ position: "absolute", left: 229, top: 923, width: 1450, height: 1, background: "rgba(22,125,141,0.18)" }} />
          <div style={{ position: "absolute", left: 247, top: 833 }}><RecordTile /></div>
          <div style={{ position: "absolute", left: 431, top: 864, fontFamily: MONO, fontSize: 20, fontWeight: 500, lineHeight: 1.5, letterSpacing: 0.2, color: C.teal }}>recorded information</div>
          <div style={{ position: "absolute", left: 1674, top: 818, width: 8, height: 8, border: "1px solid rgba(22,125,141,0.5)", background: C.ivory }} />

          {nodes.map((node, i) => {
            const topRow = i < 3;
            const targetX = node.x + 215;
            const targetY = node.y + 152;
            const startX = targetX - 102;
            const startY = 822;
            const reveal = ease(f, node.start, node.start + 13, 0, 1);
            const incoming = ease(f, node.start + 4, node.start + 35, 0, 1);
            const packetT = ease(f, node.start + 8, node.start + 38, 0, 1);
            const packetX = startX + 76 * Math.sin(packetT * Math.PI / 2);
            const packetY = startY + (targetY - startY) * (1 - Math.cos(packetT * Math.PI / 2));
            const routeOpacity = infrastructure * reveal;
            const arcHeight = startY - targetY;
            const entry = spring({ frame: Math.max(0, f - node.start), fps, config: { stiffness: 160, damping: 14, mass: 0.6 } });
            return (
              <React.Fragment key={i}>
                <div style={{ position: "absolute", left: startX, top: targetY, width: 76, height: arcHeight, borderRight: "1.35px solid rgba(22,125,141,0.24)", borderBottom: "1.35px solid rgba(22,125,141,0.24)", borderBottomRightRadius: `76px ${arcHeight}px`, opacity: routeOpacity }} />
                <div style={{ position: "absolute", left: targetX - 26, top: targetY, width: 15, height: 1.35, background: "rgba(22,125,141,0.28)", opacity: routeOpacity }} />
                <div style={{ position: "absolute", left: targetX + 1, top: node.y + 124, width: 1.35, height: 21, background: "rgba(23,40,51,0.2)", opacity: routeOpacity }} />
                <div style={{ position: "absolute", left: targetX - 3, top: targetY - 9, width: 10, height: 10, borderTop: "1.5px solid rgba(238,115,94,0.78)", borderRight: "1.5px solid rgba(238,115,94,0.78)", opacity: routeOpacity }} />
                <div style={{ position: "absolute", left: packetX - 4, top: packetY - 4, width: 8, height: 8, borderRadius: 2, background: C.teal, opacity: incoming * 0.82 }} />
                <div style={{ position: "absolute", left: node.x, top: node.y, width: 430, height: 120, borderRadius: 60, background: C.paper, border: "1px solid rgba(23,40,51,0.15)", boxShadow: "0 7px 18px rgba(23,40,51,0.045)", opacity: reveal, transform: `translateY(${(1 - entry) * 9}px) scale(${0.988 + 0.012 * entry})`, display: "flex", justifyContent: "center", alignItems: "center" }}>
                  {i === 1 && <div style={{ position: "absolute", left: 64, right: 64, bottom: 18, height: 2, background: C.cobalt, opacity: ease(f, times[14], times[14] + 12, 0, 0.74) }} />}
                  <div style={{ fontFamily: FONT, fontSize: 30, fontWeight: 400, letterSpacing: -0.6, lineHeight: 1.2, whiteSpace: "pre", color: C.graphite }}>
                    {node.parts.map((part, j) => (
                      <span key={part.text} style={{ display: "inline-block", opacity: ease(f, part.at, part.at + 7, 0, 1), transform: `translateY(${ease(f, part.at, part.at + 10, 4, 0)}px)` }}>{`${j > 0 ? " " : ""}${f >= part.at ? part.text : " ".repeat(part.text.length)}`}</span>
                    ))}
                  </div>
                </div>
              </React.Fragment>
            );
          })}

          <div style={{ position: "absolute", left: focusX, top: focusY, width: focusWidth, height: focusHeight, opacity: focusOpacity, color: C.coral, pointerEvents: "none" }}>
            <mg.FocusFrame color={C.coral} frameAt={times[11]} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", color: C.coral, borderColor: C.coral, background: "transparent" }} />
            {[0, 1, 2, 3].map((corner) => <div key={corner} style={{ position: "absolute", width: 18, height: 18, left: corner % 2 === 0 ? 0 : undefined, right: corner % 2 === 1 ? 0 : undefined, top: corner < 2 ? 0 : undefined, bottom: corner >= 2 ? 0 : undefined, borderTop: corner < 2 ? `2px solid ${C.coral}` : undefined, borderBottom: corner >= 2 ? `2px solid ${C.coral}` : undefined, borderLeft: corner % 2 === 0 ? `2px solid ${C.coral}` : undefined, borderRight: corner % 2 === 1 ? `2px solid ${C.coral}` : undefined }} />)}
          </div>
        </div>

        <div style={{ position: "absolute", left: 0, top: 0, width: 1920, height: 165, background: "linear-gradient(180deg, #F3F1E9 0%, #F3F1E9 86%, rgba(243,241,233,0) 100%)" }} />
