import React from "react";
import { AbsoluteFill, Sequence, useCurrentFrame, useVideoConfig, interpolate, spring, Easing, random } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; id?: number | string; word?: string; text?: string; startFrame: number; endFrame?: number };
type ShotProps = { wordCues?: WordCue[]; recordLabel?: string; recordInformation?: string[]; requirementsLabel?: string; requirementLabels?: string[] };

const C = { ivory: "#F3F1E9", paper: "#FFFEFA", white: "#FFFFFF", ink: "#172833", gray: "#9AA8AD", teal: "#167D8D", cobalt: "#365FDB", coral: "#EE735E" };
const sans = '"Inter", "Arial", sans-serif';
const tight = '"Inter Tight", "Inter", "Arial", sans-serif';
const mono = '"IBM Plex Mono", "Courier New", monospace';
const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
const smooth = { ...clamp, easing: Easing.inOut(Easing.cubic) };
const normalize = (s: string) => s.toLowerCase().replace(/[^a-z']/g, "");

// An HTML inspection rectangle is used so its exact line weight, padding,
// and clipping remain consistent with the typography at every camera scale.
const InspectionFrame: React.FC<{ left: number; top: number; width: number; height: number; color: string; opacity: number; openRight?: boolean }> = ({ left, top, width, height, color, opacity, openRight = false }) => (
  <div style={{ position: "absolute", left, top, width, height, boxSizing: "border-box", border: `1.5px solid ${color}`, borderRight: openRight ? "none" : `1.5px solid ${color}`, opacity, pointerEvents: "none" }}>
    {[0, 1, 2, 3].map((i) => <div key={i} style={{ position: "absolute", width: 9, height: 9, left: i % 2 === 0 ? -3 : undefined, right: i % 2 === 1 ? -3 : undefined, top: i < 2 ? -3 : undefined, bottom: i >= 2 ? -3 : undefined, background: C.paper, borderLeft: i % 2 === 0 ? `2px solid ${color}` : undefined, borderRight: i % 2 === 1 ? `2px solid ${color}` : undefined, borderTop: i < 2 ? `2px solid ${color}` : undefined, borderBottom: i >= 2 ? `2px solid ${color}` : undefined }} />)}
  </div>
);

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cueAt = (index: number, fallback: number, word: string) => {
    const direct = cues.find((c) => c.wordIndex === index || c.index === index || c.id === index || c.id === `W${index}`);
    if (direct && Number.isFinite(direct.startFrame)) return direct.startFrame;
    const local = cues.length === 25 ? cues[index - 547] : undefined;
    if (local && Number.isFinite(local.startFrame) && (!local.word && !local.text || normalize(local.word || local.text || "") === normalize(word))) return local.startFrame;
    const matches = cues.filter((c) => normalize(c.word || c.text || "") === normalize(word) && Number.isFinite(c.startFrame));
    if (matches.length) return matches.reduce((a, b) => Math.abs(a.startFrame - fallback) <= Math.abs(b.startFrame - fallback) ? a : b).startFrame;
    return fallback;
  };
  const q = {
    so: cueAt(547, 0, "So"), the: cueAt(548, 4, "the"), answer: cueAt(549, 14, "answer"), isnt: cueAt(550, 31, "isn't,"),
    blockchain: cueAt(551, 93, "blockchain"), can: cueAt(552, 123, "can"), never: cueAt(553, 134, "never"), be: cueAt(554, 147, "be"), used: cueAt(555, 155, "used"), for: cueAt(556, 165, "for"), elections: cueAt(557, 173, "elections."),
    next: cueAt(558, 251, "The"), more: cueAt(559, 261, "more"), accurate: cueAt(560, 279, "accurate"), answer2: cueAt(561, 310, "answer"), is: cueAt(562, 334, "is,"),
    blockchain2: cueAt(563, 398, "blockchain"), alone: cueAt(564, 424, "alone"), doesnt: cueAt(565, 442, "doesn't"), solve: cueAt(566, 459, "solve"), the2: cueAt(567, 476, "the"), hardest: cueAt(568, 489, "hardest"), problems: cueAt(569, 513, "problems"), in: cueAt(570, 539, "in"), elections2: cueAt(571, 543, "elections.")
  };
  const f = Math.min(frame, Math.min(565, durationInFrames - 1));
  const reveal = (at: number, length = 9) => interpolate(f, [at, at + length], [0, 1], clamp);
  const travel = (at: number, length: number) => interpolate(f, [at, at + length], [0, 1], smooth);
  const entry = spring({ frame: f - 2, fps, config: { stiffness: 160, damping: 26, mass: 1 }, durationInFrames: 28 });
  const push = travel(2, 28);
