  const zoom = zoomDetail + (1 - zoomDetail) * pullback;
  const upperX = 960 - 27 * push + 65 * inspect;
  const upperY = 540 - 5 * push;
  const cameraX = (upperX + (975 - upperX) * descend) * (1 - pullback) + 960 * pullback;
  const cameraY = (upperY + (647 - upperY) * descend) * (1 - pullback) + 540 * pullback;
  const panX = zoom * (960 - cameraX);
  const panY = zoom * (540 - cameraY);
  const sheetOpacity = interpolate(f, [2, 10], [0, 1], clamp);
  const statementTone = interpolate(f, [q.next, q.next + 28], [1, 0.49], clamp);
  const neutralOpacity = reveal(q.blockchain, 12) * (1 - travel(q.next, 28));
