  const scopeWidth = interpolate(f, [q.blockchain2, q.blockchain2 + 20, q.alone, q.alone + 14, q.doesnt, q.solve + 16], [298, 298, 298, 444, 444, 876], smooth);
  const scopeHeight = interpolate(f, [q.hardest, q.elections2 + 21], [80, 170], smooth);
  const aloneMark = reveal(q.alone, 12);
  const scanX = interpolate(f, [q.blockchain, q.can, q.never, q.be, q.used, q.for, q.elections, q.elections + 34], [244, 485, 572, 703, 770, 886, 970, 1198], clamp);
  const recordLabel = props.recordLabel || "Blockchain record";
  const recordFields = props.recordInformation || ["Recorded selection", "Timestamp", "Record hash"];
  const requirementsLabel = props.requirementsLabel || "Election requirements";
  const requirementLabels = props.requirementLabels || ["Voter eligibility", "Ballot secrecy", "Coercion resistance"];
  const scale = Math.min(width / 1920, height / 1080);

  const spoken = (text: string, at: number, key: string) => <span key={key} style={{ display: "inline-block", opacity: reveal(at, 7), transform: `translateY(${(1 - reveal(at, 7)) * 5}px)` }}>{text}</span>;
  const lowerWord = (text: string, at: number, left: number, top: number, key: string) => <span key={key} style={{ position: "absolute", left, top, whiteSpace: "pre", opacity: 0.29 + 0.71 * reveal(at, 10), color: C.ink }}>{text}</span>;

  return (
    <AbsoluteFill style={{ backgroundColor: C.ivory, overflow: "hidden", fontFamily: sans, color: C.ink }}>
