import React from "react";
import { AbsoluteFill, Sequence, useCurrentFrame, useVideoConfig, interpolate, spring, Easing, random } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; id?: string | number; startFrame?: number; start?: number; word?: string; text?: string };
type ShotProps = { wordCues?: WordCue[] };

const C = {
  ivory: "#F3F1E9",
  white: "#FFFFFF",
  graphite: "#172833",
  gray: "#9AA8AD",
  teal: "#167D8D",
  cobalt: "#365FDB",
  coral: "#EE735E"
};
const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
const stageFont = '"Inter", Arial, sans-serif';
const monoFont = '"IBM Plex Mono", monospace';
const headingFont = '"Inter Tight", "Inter", Arial, sans-serif';

const Ballot = () => (
  <svg width="790" height="626" viewBox="0 0 790 626" fill="none" aria-label="Blank ballot schematic with three unmarked choices" style={{ display: "block", overflow: "visible" }}>
    <path d="M28 2H686L788 104V604Q788 624 768 624H28Q2 624 2 598V28Q2 2 28 2Z" fill={C.white} fillOpacity="0.79" stroke={C.graphite} strokeOpacity="0.5" strokeWidth="2" />
    <path d="M686 2V104H788" fill={C.ivory} fillOpacity="0.8" stroke={C.graphite} strokeOpacity="0.5" strokeWidth="2" strokeLinejoin="round" />
    <path d="M57 61H484" stroke={C.graphite} strokeOpacity="0.56" strokeWidth="5" strokeLinecap="round" />
    <rect x="58" y="122" width="39" height="39" rx="2" stroke={C.graphite} strokeOpacity="0.68" strokeWidth="2.3" />
    <rect x="58" y="196" width="39" height="39" rx="2" stroke={C.graphite} strokeOpacity="0.68" strokeWidth="2.3" />
    <rect x="58" y="270" width="39" height="39" rx="2" stroke={C.graphite} strokeOpacity="0.68" strokeWidth="2.3" />
