const OpenJunction: React.FC<{ x: number; y: number; color?: string; size?: number; opacity?: number }> = ({ x, y, color = C.graphite, size = 26, opacity = 1 }) => (
  <div style={{ position: "absolute", left: x - size / 2, top: y - size / 2, width: size, height: size, color, opacity }}>
    {[0, 1, 2, 3].map((corner) => (
      <div key={corner} style={{ position: "absolute", width: size * 0.34, height: size * 0.34, left: corner % 2 === 0 ? 0 : undefined, right: corner % 2 === 1 ? 0 : undefined, top: corner < 2 ? 0 : undefined, bottom: corner >= 2 ? 0 : undefined, borderLeft: corner % 2 === 0 ? "2px solid currentColor" : undefined, borderRight: corner % 2 === 1 ? "2px solid currentColor" : undefined, borderTop: corner < 2 ? "2px solid currentColor" : undefined, borderBottom: corner >= 2 ? "2px solid currentColor" : undefined }} />
    ))}
  </div>
);

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];

  const cueAt = (wordIndex: number, fallback: number, token: string) => {
    const normalized = token.toLowerCase().replace(/[^a-z]/g, "");
    const byIndex = cues.find((cue) => cue.wordIndex === wordIndex || cue.index === wordIndex || String(cue.id) === String(wordIndex) || cue.id === `W${wordIndex}`);
    const byWord = cues.find((cue) => (cue.word || cue.text || "").toLowerCase().replace(/[^a-z]/g, "") === normalized);
    const cue = byIndex || byWord;
    const value = cue?.startFrame;
    return typeof value === "number" && Number.isFinite(value) ? value : fallback;
  };
  const ballotAt = cueAt(581, 193, "ballot");
  const securityAt = cueAt(583, 256, "security");
  const publicAt = cueAt(585, 331, "public");
  const pushAt = cueAt(587, 418, "putting");
  const blockchainAt = cueAt(590, 469, "blockchain");
  const mightAt = cueAt(591, 525, "might");
  const pulseAt = cueAt(592, 543, "give");
  const pullAt = cueAt(598, 726, "while");
  const pushEnd = Math.max(pushAt + 1, blockchainAt + 31);
  const pullEnd = pullAt + 101;
  const shotFrame = Math.min(frame, Math.max(0, durationInFrames - 1));

  const entrance = interpolate(shotFrame, [2, 30], [0, 1], { ...clamp, easing: Easing.out(Easing.cubic) });
  const enterSpring = spring({ fps, frame: Math.max(0, shotFrame - 2), config: { stiffness: 160, damping: 14, mass: 0.8 } });
  const push = interpolate(shotFrame, [pushAt, pushEnd], [0, 1], { ...clamp, easing: Easing.inOut(Easing.cubic) });
  const damped = (t: number) => {
    const k = 9;
    const end = 1 - (1 + k) * Math.exp(-k);
    return (1 - (1 + k * t) * Math.exp(-k * t)) / end;
  };
  const pull = interpolate(shotFrame, [pullAt, pullEnd], [0, 1], { ...clamp, easing: damped });
  const inspection = push * (1 - pull);
  const zoom = 1 + 0.29 * inspection;
  const centerX = 860 + 50 * inspection;
  const centerY = 450 + 94 * inspection;
  const panX = 860 - centerX * zoom;
  const panY = 450 - centerY * zoom;
  const viewScale = Math.min(width / 1920, height / 1080);
  const viewLeft = (width - 1920 * viewScale) / 2;
  const viewTop = (height - 1080 * viewScale) / 2;

  const tray = { x: 452, y: 458, width: 886, height: 213 };
  const original = { x: 482, y: 517, width: 110, height: 114 };
  const boundary = { x: 44, y: 74, width: 1632, height: 782 };
  const focusMix = pull;
  const mix = (a: number, b: number) => a + (b - a) * focusMix;
  const focusX = mix(tray.x - 15, boundary.x - 12);
  const focusY = mix(tray.y - 15, boundary.y - 12);
  const focusW = mix(tray.width + 30, boundary.width + 24);
  const focusH = mix(tray.height + 30, boundary.height + 24);
  const focusOpacity = interpolate(shotFrame, [pushAt, pushAt + 25], [0, 0.95], clamp);
  const tabEnter = spring({ fps, frame: Math.max(0, shotFrame - mightAt), config: { stiffness: 160, damping: 14, mass: 0.65 } });
  const tabOpacity = interpolate(shotFrame, [mightAt, mightAt + 9], [0, 1], clamp);
  const pulseProgress = interpolate(shotFrame, [pulseAt, pulseAt + 32], [0, 1], clamp);
  const pulseX = 501 + (1271 - 501) * pulseProgress;
  const pulseOpacity = interpolate(shotFrame, [pulseAt, pulseAt + 3, pulseAt + 28, pulseAt + 32], [0, 0.9, 0.9, 0], clamp);

  const railData = [
    { label: "ballot secrecy", at: ballotAt, x: 362 },
    { label: "security", at: securityAt, x: 860 },
    { label: "public trust", at: publicAt, x: 1358 }
  ];

  const recordTile = (i: number) => {
    const isOriginal = i === 0;
    const tileDelay = 3 + i * 2;
    const tileSpring = spring({ fps, frame: Math.max(0, shotFrame - tileDelay), config: { stiffness: 160, damping: 14, mass: 0.55 } });
    const opacity = isOriginal ? 1 : interpolate(shotFrame, [tileDelay, tileDelay + 10], [0, 1], clamp);
    const x = original.x + i * 143;
    const passing = Math.max(0, 1 - Math.abs(pulseX - (x + 55)) / 94) * pulseOpacity;
    const tile = (
      <div style={{ position: "absolute", left: x, top: original.y, width: original.width, height: original.height, boxSizing: "border-box", border: `1.5px solid ${isOriginal ? C.teal : "rgba(22,125,141,0.38)"}`, borderRadius: 7, background: isOriginal ? C.teal : "rgba(22,125,141,0.055)", boxShadow: isOriginal ? "0 8px 19px rgba(22,125,141,0.13)" : "0 3px 8px rgba(23,40,51,0.025)", opacity, transform: isOriginal ? "none" : `translateY(${(1 - tileSpring) * 12}px)`, overflow: "hidden" }}>
        <div style={{ position: "absolute", left: 15, top: 17, width: 18, height: 18, border: `1.5px solid ${isOriginal ? "rgba(255,255,255,0.82)" : "rgba(22,125,141,0.6)"}`, borderRadius: 2 }} />
        {[0, 1, 2].map((r) => <div key={r} style={{ position: "absolute", left: 15, top: 55 + r * 13, width: r === 1 ? 52 : 75, height: 2, background: isOriginal ? "rgba(255,255,255,0.76)" : "rgba(22,125,141,0.44)" }} />)}
        <div style={{ position: "absolute", right: 13, top: 18, height: 14, width: 3, background: isOriginal ? "rgba(255,255,255,0.66)" : "rgba(22,125,141,0.4)" }} />
        <div style={{ position: "absolute", inset: 0, background: isOriginal ? "rgba(255,255,255,0.12)" : "rgba(22,125,141,0.12)", opacity: passing }} />
      </div>
    );
    // The original tile stays outside the entrance animation at its inherited screen anchor.
    return <React.Fragment key={i}>{tile}</React.Fragment>;
  };

  return (
    <AbsoluteFill style={{ background: C.ivory, overflow: "hidden", color: C.graphite, fontFamily: stageFont }}>
      <div style={{ position: "absolute", left: viewLeft, top: viewTop, width: 1920, height: 1080, transform: `scale(${viewScale})`, transformOrigin: "0 0" }}>
        <AbsoluteFill style={{ background: "radial-gradient(ellipse at 52% 50%, rgba(255,255,255,0.87) 0%, rgba(255,255,255,0.2) 48%, rgba(243,241,233,0) 78%)" }} />
        <div style={{ position: "absolute", inset: 0, opacity: 0.14, backgroundImage: "radial-gradient(rgba(23,40,51,0.32) 0.75px, transparent 0.85px)", backgroundSize: "32px 32px", maskImage: "linear-gradient(to bottom, transparent 11%, black 32%, black 87%, transparent)" }} />

        {/* The typography strip is intentionally outside both spatial transforms. */}
        <div style={{ position: "absolute", left: 100, top: 45, width: 1190, height: 110, zIndex: 10, pointerEvents: "none" }}>
          <mg.Heading kicker="ELECTION SYSTEMS / SCOPE OF PROOF" title="A database is not an election" frameAt={2} style={{ position: "absolute", left: 0, top: 0, maxWidth: 1190, fontFamily: headingFont, fontSize: 50, fontWeight: 600, lineHeight: 1.05, letterSpacing: -1.4, color: C.graphite }} />
        </div>

        <div style={{ position: "absolute", left: 100, top: 160, width: 1720, height: 900, overflow: "hidden", borderRadius: 4, background: "linear-gradient(145deg, rgba(255,255,255,0.48), rgba(255,255,255,0.07))", boxShadow: "inset 0 0 0 1px rgba(23,40,51,0.055)" }}>
          <div style={{ position: "absolute", inset: 0, transform: `translate(${panX}px, ${panY}px) scale(${zoom})`, transformOrigin: "0 0" }}>

            {/* An open perimeter: no enclosing check, seal, verdict, or pass/fail state. */}
            <svg width="1720" height="900" viewBox="0 0 1720 900" fill="none" style={{ position: "absolute", inset: 0, opacity: 0.63 + entrance * 0.37 }}>
              <path d="M44 320V100Q44 74 70 74H214 M472 74H1238 M1496 74H1650Q1676 74 1676 100V320 M1676 408V830Q1676 856 1650 856H1138 M974 856H746 M582 856H70Q44 856 44 830V408" stroke={C.graphite} strokeOpacity="0.67" strokeWidth="2.2" strokeLinecap="square" />
              <path d="M88 111H133 M88 111V156 M1632 111H1587 M1632 111V156 M88 819H133 M88 819V774 M1632 819H1587 M1632 819V774" stroke={C.gray} strokeOpacity="0.31" strokeWidth="1" />
              <path d="M208 249H1512" stroke={C.gray} strokeOpacity="0.11" strokeWidth="1" />
            </svg>

            {/* Ten and only ten drawing elements make up the ballot illustration. */}
            <div style={{ position: "absolute", left: 480, top: 221 + (1 - entrance) * 8, width: 790, height: 626, opacity: 0.8 + entrance * 0.2, filter: "drop-shadow(0 9px 13px rgba(23,40,51,0.045))" }}>
              <Ballot />
            </div>

            {/* Fixed rail sites exist first; each full requirement appears at its spoken cue. */}
            {railData.map((rail, index) => {
              const labelSpring = spring({ fps, frame: Math.max(0, shotFrame - rail.at), config: { stiffness: 160, damping: 14, mass: 0.72 } });
              const labelAlpha = interpolate(shotFrame, [rail.at, rail.at + 12], [0, 1], clamp);
              return (
                <React.Fragment key={rail.label}>
                  <div style={{ position: "absolute", left: rail.x - 150, top: 88, width: 300, height: 72, borderRadius: 3, border: "1px solid rgba(23,40,51,0.16)", background: "rgba(255,255,255,0.58)", boxShadow: "0 4px 12px rgba(23,40,51,0.018)", opacity: 0.72 + entrance * 0.28 }} />
                  <div style={{ position: "absolute", left: rail.x - 9, top: 160, width: 18, height: 22, background: "rgba(23,40,51,0.022)", borderLeft: "1px solid rgba(23,40,51,0.24)", borderRight: "1px solid rgba(23,40,51,0.24)" }} />
                  <OpenJunction x={rail.x} y={199} size={28} opacity={0.45 + labelAlpha * 0.32} />
                  <div style={{ position: "absolute", left: rail.x - 153, top: 89, width: 306, height: 71, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 30, fontWeight: 400, letterSpacing: -0.65, opacity: labelAlpha, transform: `translateY(${(1 - labelSpring) * 9}px)`, whiteSpace: "nowrap" }}>{rail.label}</div>
                </React.Fragment>
              );
            })}

            {/* Cobalt evidence stays on a distinct route, ending outside the record tray. */}
            <div style={{ position: "absolute", left: 104, top: 602, width: 84, height: 101, boxSizing: "border-box", borderRadius: 4, border: "1.5px solid rgba(54,95,219,0.53)", background: "rgba(54,95,219,0.035)", boxShadow: "-7px 7px 0 rgba(54,95,219,0.025)" }}>
              <div style={{ position: "absolute", left: 15, top: 17, width: 21, height: 21, border: "1.5px solid rgba(54,95,219,0.65)", borderRadius: 2 }} />
              {[0, 1, 2].map((i) => <div key={i} style={{ position: "absolute", left: 15, top: 52 + i * 12, width: i === 1 ? 34 : 51, height: 1.5, background: "rgba(54,95,219,0.48)" }} />)}
            </div>
            <svg width="1720" height="900" viewBox="0 0 1720 900" fill="none" style={{ position: "absolute", inset: 0 }}>
              <path d="M189 652H259Q277 652 277 634V618Q277 604 291 604H337" stroke={C.cobalt} strokeWidth="1.65" strokeOpacity="0.82" />
            </svg>
            <OpenJunction x={355} y={604} size={30} color={C.cobalt} opacity={0.82} />

            {/* The glass tray assembles around the unchanged teal tile, not vice versa. */}
            <div style={{ position: "absolute", left: tray.x, top: tray.y, width: tray.width, height: tray.height, transform: `scaleX(${0.82 + 0.18 * entrance}) scaleY(${0.9 + 0.1 * entrance})`, transformOrigin: "85px 116px", opacity: entrance, borderRadius: 12, boxSizing: "border-box", border: "1.4px solid rgba(23,40,51,0.24)", background: "linear-gradient(175deg, rgba(255,255,255,0.89), rgba(255,255,255,0.7))", boxShadow: "0 16px 34px rgba(23,40,51,0.055), inset 0 1px 0 rgba(255,255,255,0.96)" }}>
              <div style={{ position: "absolute", left: 0, right: 0, top: 42, borderTop: "1px solid rgba(23,40,51,0.095)" }} />
              <div style={{ position: "absolute", left: 26, top: 14, width: 42, height: 5, background: "rgba(22,125,141,0.34)", borderRadius: 1 }} />
              <div style={{ position: "absolute", right: 25, top: 14, width: 18, height: 12, borderLeft: "1px solid rgba(23,40,51,0.3)", borderRight: "1px solid rgba(23,40,51,0.3)" }} />
              <div style={{ position: "absolute", left: 16, right: 16, bottom: 10, height: 1, background: "rgba(23,40,51,0.07)" }} />
            </div>

            {/* Aligned copies are purely geometric: no count or quantitative claim. */}
            {[0, 1, 2, 3, 4, 5].map(recordTile)}
            <svg width="1720" height="900" viewBox="0 0 1720 900" fill="none" style={{ position: "absolute", inset: 0, opacity: entrance, pointerEvents: "none" }}>
              <path d="M501 644H1271" stroke={C.teal} strokeOpacity="0.19" strokeWidth="1" />
              {[0, 1, 2, 3, 4, 5].map((i) => <path key={i} d={`M${537 + i * 143} 639V649`} stroke={C.teal} strokeOpacity="0.5" strokeWidth="1.4" />)}
            </svg>

            {/* One finite registration pass denotes internal record alignment only. */}
            <div style={{ position: "absolute", left: pulseX - 20, top: 642, width: 40, height: 4, borderRadius: 3, background: `linear-gradient(90deg, transparent, ${C.teal}, transparent)`, opacity: pulseOpacity, boxShadow: "0 0 8px rgba(22,125,141,0.2)" }} />
            <div style={{ position: "absolute", left: pulseX - 3, top: 640, width: 6, height: 8, borderRadius: 1, background: C.teal, opacity: pulseOpacity }} />

            {/* The modal word remains attached to the database, even after the pullback. */}
