  let focus = { ...byId("phone") };
  for (let i = 1; i < inspections.length; i++) {
    if (frame >= inspections[i].at) {
      const from = byId(inspections[i - 1].id);
      const to = byId(inspections[i].id);
      const t = phase(frame, inspections[i].at, inspections[i].at + 30);
      focus = { ...to, x: mix(from.x, to.x, t), y: mix(from.y, to.y, t), w: mix(from.w, to.w, t), h: mix(from.h, to.h, t) };
    }
  }
  const focusOpacity = phase(frame, 2, phoneAt + 6) * (1 - phase(frame, 661, 691));
  const statusData: Partial<Record<NodeId, { at: number; words: { text: string; at: number }[] }>> = {
    phone: { at: cue(392, 27), words: [{ text: "can", at: cue(392, 27) }, { text: "be", at: cue(393, 36) }, { text: "hacked", at: cue(394, 46) }] },
    computer: { at: cue(397, 148), words: [{ text: "can", at: cue(397, 148) }, { text: "be", at: cue(398, 157) }, { text: "infected", at: cue(399, 163) }] },
    application: { at: cue(403, 292), words: [{ text: "can", at: cue(403, 292) }, { text: "have", at: cue(404, 304) }, { text: "vulnerabilities", at: cue(405, 317) }] },
    identity: { at: cue(409, 472), words: [{ text: "can", at: cue(409, 472) }, { text: "be", at: cue(410, 485) }, { text: "compromised", at: cue(411, 492) }] },
    servers: { at: cue(413, 612), words: [{ text: "can", at: cue(413, 612) }, { text: "be", at: cue(414, 623) }, { text: "attacked", at: cue(415, 631) }] }
  };

  const demoOpacity = phase(frame, ifAt, ifAt + 14);
  const selection = phase(frame, changeAt, voteAt + 18);
  const trip = phase(frame, beforeAt, 935);
  const tileX = interpolate(frame, [beforeAt, reachesAt, blockchainAt, 935], [604, 968, 1052, 1175], { ...clamp, easing: ease });
  const recorded = frame >= blockchainAt;
  const inheritedOpacity = 0.78 * (1 - phase(frame, andAt, andAt + 24));
  const changedGhost = phase(frame, beforeAt + 9, beforeAt + 25);
  const copyOne = phase(frame, storeAt, 1080);
  const copyTwo = phase(frame, wrongAt + 4, 1119);
  const copyingOpacity = phase(frame, storeAt, storeAt + 12);
  const resolveOpacity = phase(frame, foreverAt, 1119);
  const pointAlong = (points: number[][], t: number) => {
    const lengths = points.slice(1).map((p, i) => Math.hypot(p[0] - points[i][0], p[1] - points[i][1]));
    const total = lengths.reduce((sum, n) => sum + n, 0);
    let distance = total * t;
    for (let i = 0; i < lengths.length; i++) {
      if (distance <= lengths[i] || i === lengths.length - 1) {
        const local = lengths[i] === 0 ? 0 : Math.min(1, distance / lengths[i]);
        return { x: mix(points[i][0], points[i + 1][0], local), y: mix(points[i][1], points[i + 1][1], local) };
      }
      distance -= lengths[i];
    }
    return { x: points[0][0], y: points[0][1] };
  };
  const packet = (key: string, points: number[][], start: number, end: number, color: string) => {
    const p = pointAlong(points, phase(frame, start, end));
    const opacity = phase(frame, start, start + 8) * (1 - phase(frame, end - 8, end));
    return <div key={key} style={{ position: "absolute", left: p.x - 5, top: p.y - 5, width: 10, height: 10, borderRadius: 2, background: color, opacity }} />;
  };
  const replicaTile = (p: number, destinationY: number, activeAt: number) => (
    <div style={{ position: "absolute", left: mix(1175, 1498, p), top: mix(624, destinationY, p), opacity: phase(frame, activeAt, activeAt + 7), zIndex: 10 }}>
      <Tile mark={1} recorded />
    </div>
  );

  return (
    <AbsoluteFill style={{ background: C.ivory, color: C.graphite, fontFamily: sans, overflow: "hidden" }}>
      <div style={{ position: "absolute", width: 1920, height: 1080, left: 0, top: 0, transform: `scale(${width / 1920}, ${height / 1080})`, transformOrigin: "0 0" }}>
        <div style={{ position: "absolute", inset: 0, background: "radial-gradient(ellipse at 60% 42%, rgba(255,255,255,0.8), transparent 68%)" }} />
        <mg.Heading kicker="Conceptual map" title="Other components" frameAt={2} style={{ position: "absolute", left: 100, top: 40, maxWidth: 1100, fontFamily: tight, fontSize: 52, fontWeight: 600, lineHeight: 1.06, color: C.graphite, zIndex: 30 }} />
        <div style={{ position: "absolute", left: 110, top: 160, width: 1700, height: 900, border: "1px solid rgba(23,40,51,0.13)", borderRadius: 18, boxSizing: "border-box", overflow: "hidden", background: "rgba(255,255,255,0.58)", boxShadow: "0 16px 55px rgba(23,40,51,0.035)", opacity: chapterFade }}>
          <div style={{ position: "absolute", width: 1700, height: 900, transformOrigin: "0 0", transform: `translate(${panX}px, ${panY}px) scale(${camera.z})` }}>
            <div style={{ position: "absolute", inset: -1800, backgroundImage: "radial-gradient(circle, rgba(23,40,51,0.12) 0.8px, transparent 1px)", backgroundSize: "48px 48px", opacity: 0.5 }} />
            <svg width={1700} height={900} viewBox="0 0 1700 900" style={{ position: "absolute", inset: 0, overflow: "visible" }} aria-hidden="true">
              <path d="M 412 199 H 450 Q 470 199 470 219 V 328 Q 470 348 490 348 H 505" fill="none" stroke={C.gray} strokeWidth={2} opacity={0.56} />
              <path d="M 412 447 H 450 Q 470 447 470 427 V 424 Q 470 404 490 404 H 505" fill="none" stroke={C.gray} strokeWidth={2} opacity={0.56} />
              <path d="M 724 478 V 508 Q 724 528 704 528 H 492 Q 472 528 472 548 V 660 Q 472 680 492 680 H 1124" fill="none" stroke={C.gray} strokeWidth={2} opacity={0.68} />
              <path d="M 1124 680 H 1390" fill="none" stroke={C.teal} strokeWidth={2} opacity={0.26} />
              <path d="M 1210 236 V 266 H 1538 V 303 H 1150 V 500" fill="none" stroke={C.cobalt} strokeWidth={1.5} strokeDasharray="5 8" opacity={0.42 * phase(frame, identityAt, identityAt + 26)} />
              <path d="M 1142 500 H 1158" fill="none" stroke={C.cobalt} strokeWidth={1.5} opacity={0.6 * phase(frame, identityAt, identityAt + 26)} />
              <path d="M 1390 680 H 1422 V 456 H 1460 M 1422 680 V 733 H 1460" fill="none" stroke={C.teal} strokeWidth={1.5} opacity={0.34 * phase(frame, returnAt, returnAt + 36)} />
              <path d="M 620 594 V 766" fill="none" stroke={C.coral} strokeWidth={2} opacity={demoOpacity} />
              <path d="M 612 594 H 628 M 612 766 H 628" fill="none" stroke={C.coral} strokeWidth={2} opacity={demoOpacity} />
              <path d="M 1124 525 V 832" fill="none" stroke={C.teal} strokeWidth={2} opacity={demoOpacity} />
            </svg>

            {nodes.map((node) => {
              const unfold = spring({ frame: frame - node.at, fps, config: { stiffness: 160, damping: 14 }, durationInFrames: 28 });
              const isReplica = node.id === "replica1" || node.id === "replica2";
              const pending = frame < node.at;
              const block = node.id === "blockchain";
              const status = statusData[node.id];
              const inspectionIndex = inspections.findIndex((item) => item.id === node.id);
              const nextInspectAt = inspectionIndex >= 0 && inspectionIndex < 4 ? inspections[inspectionIndex + 1].at : 661;
              const statusTone = phase(frame, nextInspectAt, nextInspectAt + 24);
              const nodeOpacity = isReplica ? phase(frame, node.at, node.at + 24) : pending ? 0.7 : 1;
              const scaleY = isReplica ? 0.88 + 0.12 * unfold : 0.88 + 0.12 * unfold;
              return (
                <div key={node.id} style={{ position: "absolute", left: node.x, top: node.y, width: node.w, height: node.h, boxSizing: "border-box", transform: `translateY(${(1 - unfold) * 7}px) scaleY(${scaleY})`, transformOrigin: "50% 50%", opacity: nodeOpacity, border: `1px solid ${node.accent === C.cobalt ? "rgba(54,95,219,0.40)" : block ? "rgba(22,125,141,0.36)" : "rgba(23,40,51,0.22)"}`, borderRadius: 11, background: node.id === "identity" ? "rgba(239,243,255,0.96)" : block || isReplica ? "rgba(251,255,254,0.94)" : "rgba(255,255,255,0.93)", boxShadow: "0 8px 21px rgba(23,40,51,0.035)", zIndex: 3 }}>
                  <div style={{ position: "absolute", left: 25, right: 25, top: 23, height: 3, background: node.accent || C.graphite, opacity: node.id === "identity" ? 0.84 : 0.18 }} />
                  <div style={{ position: "absolute", left: 25, top: 44, right: 15, fontFamily: sans, fontSize: isReplica ? 29 : 32, lineHeight: 1.18, fontWeight: 500, color: node.id === "identity" ? C.cobalt : C.graphite, whiteSpace: "nowrap" }}>{node.title}</div>
                  {status && (
                    <div style={{ position: "absolute", left: 25, right: 17, top: node.id === "identity" ? 108 : 117, opacity: phase(frame, status.at, status.at + 5), fontFamily: mono, fontSize: 22, lineHeight: 1.2, letterSpacing: -0.7, color: C.graphite, display: "flex", gap: 9, alignItems: "center", whiteSpace: "nowrap" }}>
                      <span style={{ width: 2, height: 21, background: statusTone < 0.5 ? C.coral : C.gray, opacity: 0.8, flexShrink: 0 }} />
                      {status.words.map((word, i) => <span key={i} style={{ opacity: phase(frame, word.at, word.at + 5) * (1 - 0.28 * statusTone), transform: `translateY(${4 * (1 - phase(frame, word.at, word.at + 6))}px)` }}>{word.text}</span>)}
                    </div>
                  )}
                  {node.id === "servers" && <div style={{ position: "absolute", left: 0, right: 0, top: 177, height: 1, background: C.gray, opacity: 0.4 }} />}
                  {block && <div style={{ position: "absolute", left: 51, top: 64, opacity: inheritedOpacity, transform: "translateY(28px)" }}><Tile mark={0} recorded /></div>}
                  {block && <div style={{ position: "absolute", left: 25, bottom: 17, fontFamily: mono, fontSize: 18, color: C.teal, opacity: phase(frame, storeAt, storeAt + 14) }}>recorded version</div>}
                  {isReplica && <div style={{ position: "absolute", left: 38, top: 81, width: 144, height: 112, border: "1px solid rgba(22,125,141,0.13)", boxSizing: "border-box", borderRadius: 6 }} />}
                  {isReplica && <div style={{ position: "absolute", bottom: 13, left: 38, fontFamily: mono, fontSize: 18, color: C.teal, opacity: node.id === "replica1" ? phase(frame, 1080, 1094) : resolveOpacity }}>unchanged</div>}
                </div>
              );
            })}

            <div style={{ position: "absolute", left: focus.x - 10, top: focus.y - 10, width: focus.w + 20, height: focus.h + 20, opacity: focusOpacity, zIndex: 7, pointerEvents: "none" }}>
              <mg.FocusFrame color={C.coral} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", color: C.coral, borderColor: C.coral, borderRadius: 14 }} />
            </div>

            {packet("phone-route", [[412, 199], [470, 199], [470, 348], [505, 348]], cue(394, 46) + 16, computerAt + 5, C.graphite)}
            {packet("computer-route", [[412, 447], [470, 447], [470, 404], [505, 404]], cue(399, 163) + 18, applicationAt + 12, C.graphite)}
            {packet("application-route", [[724, 478], [724, 528], [492, 528], [472, 548]], cue(405, 317) + 19, identityAt - 8, C.graphite)}
            {packet("evidence-route", [[1210, 236], [1210, 266], [1538, 266], [1538, 303], [1150, 303], [1150, 500]], cue(411, 492) + 7, serversAt - 4, C.cobalt)}
            {packet("server-route", [[972, 680], [1045, 680], [1118, 680]], cue(415, 631) + 4, 688, C.graphite)}

            <div style={{ position: "absolute", left: 1196, top: 278, fontFamily: mono, fontSize: 19, color: C.cobalt, background: C.ivory, padding: "4px 10px", opacity: phase(frame, identityAt + 12, identityAt + 32), zIndex: 4 }}>identity evidence</div>

            <div style={{ position: "absolute", left: 290, top: 568, opacity: demoOpacity, zIndex: 6, display: "flex", alignItems: "center", gap: 16 }}>
              <div style={{ padding: "5px 15px 7px", border: `1px solid ${C.coral}`, borderRadius: 5, background: "#FFF4F0", color: C.graphite, fontFamily: tight, fontWeight: 600, fontSize: 30 }}>if</div>
              <div style={{ fontFamily: mono, fontSize: 19, color: C.graphite, letterSpacing: 0.2 }}>illustrative selection</div>
            </div>
            <div style={{ position: "absolute", left: 274, top: 613, width: 402, height: 176, border: "1px solid rgba(238,115,94,0.32)", borderRadius: 9, background: "rgba(255,250,247,0.56)", opacity: demoOpacity, zIndex: 4 }} />
            <div style={{ position: "absolute", left: 296, top: 638, opacity: demoOpacity, zIndex: 6 }}><Tile mark={0} /></div>
            <div style={{ position: "absolute", left: 454, top: 693, width: 47, height: 1, background: C.coral, opacity: demoOpacity, zIndex: 6 }} />
            <div style={{ position: "absolute", left: 493, top: 689, width: 8, height: 8, borderRight: `1px solid ${C.coral}`, borderTop: `1px solid ${C.coral}`, transform: "rotate(45deg)", opacity: demoOpacity, zIndex: 6 }} />
            <div style={{ position: "absolute", left: 519, top: 638, opacity: changedGhost, zIndex: 6 }}><Tile mark={1} ghost /></div>
            <div style={{ position: "absolute", left: 567, top: 797, fontFamily: mono, fontSize: 20, color: C.coral, opacity: phase(frame, changeAt, changeAt + 10), zIndex: 6 }}>change gate</div>
            <div style={{ position: "absolute", left: 1018, top: 490, width: 230, textAlign: "center", fontFamily: mono, fontSize: 20, color: C.teal, opacity: phase(frame, beforeAt, beforeAt + 16), zIndex: 6 }}>recording boundary</div>

            <div style={{ position: "absolute", left: frame < beforeAt ? mix(519, 604, phase(frame, 797, beforeAt)) : tileX, top: frame < beforeAt ? mix(638, 624, phase(frame, 797, beforeAt)) : 624, opacity: demoOpacity, zIndex: 12 }}>
              <Tile mark={selection} recorded={recorded} />
              <div style={{ position: "absolute", inset: -7, border: "1px solid rgba(238,115,94,0.58)", borderRadius: 10, opacity: (1 - phase(frame, blockchainAt, blockchainAt + 14)) * phase(frame, changeAt, changeAt + 10) }} />
            </div>
            <div style={{ position: "absolute", left: 1117, top: 600, width: 14, height: 160, background: "rgba(22,125,141,0.12)", opacity: phase(frame, blockchainAt - 4, blockchainAt + 3) * (1 - phase(frame, blockchainAt + 10, blockchainAt + 27)), zIndex: 11 }} />

            {replicaTile(copyOne, 422, storeAt)}
            {replicaTile(copyTwo, 699, wrongAt + 4)}
            {packet("copy-a", [[1390, 680], [1422, 680], [1422, 456], [1460, 456]], storeAt, 1080, C.teal)}
            {packet("copy-b", [[1390, 680], [1422, 680], [1422, 733], [1460, 733]], wrongAt + 4, 1119, C.teal)}

            <div style={{ position: "absolute", left: 288, top: 850, width: 379, height: 2, background: C.coral, opacity: phase(frame, returnAt, 1038) * 0.48 }} />
            <div style={{ position: "absolute", left: 1124, top: 870, width: 556, height: 2, background: C.teal, opacity: copyingOpacity * 0.48 }} />
            <div style={{ position: "absolute", left: 99, top: 875, width: 897, height: 1, background: C.graphite, opacity: 0.14 * handoff }} />
          </div>

          <div style={{ position: "absolute", left: 30, top: 30, width: 18, height: 18, borderTop: "1px solid rgba(23,40,51,0.22)", borderLeft: "1px solid rgba(23,40,51,0.22)", opacity: Math.min(1, plateIn) }} />
          <div style={{ position: "absolute", right: 30, bottom: 30, width: 18, height: 18, borderBottom: "1px solid rgba(23,40,51,0.22)", borderRight: "1px solid rgba(23,40,51,0.22)" }} />
          <div style={{ position: "absolute", left: 42, top: 43, width: 800, height: 811, border: "1px solid rgba(23,40,51,0.18)", borderRadius: 12, opacity: 0.48 * handoff, pointerEvents: "none" }} />
          <div style={{ position: "absolute", left: 866, top: 43, width: 791, height: 811, border: "1px solid rgba(23,40,51,0.18)", borderRadius: 12, opacity: 0.48 * handoff, pointerEvents: "none" }} />
        </div>
      </div>
    </AbsoluteFill>
  );
};
